// ── Question Bank Service ─────────────────────────────────────────────────────
// Stores 50 Q&As per domain in Firestore and provides read functions.
// Run seedQuestionsToFirestore() once from the app to populate the DB.

import { collection, doc, setDoc, getDoc, getDocs } from 'firebase/firestore';
