export interface QAItem {
  question: string;
  modelAnswer: string;
  keywords: string[];
  example: string;
  difficulty: 'Beginner' | 'Intermediate' | 'Advanced';
}

// ── COMPLETE QUESTION BANK ────────────────────────────────────────────────────
// 50 questions per domain × 6 domains = 300+ total Q&A pairs

const QUESTION_BANK: Record<string, QAItem[]> = {

  // ══════════════════════════════════════════════════════════════
  // JAVASCRIPT  —  50 questions
  // ══════════════════════════════════════════════════════════════
  JavaScript: [
    // ── Beginner (17) ──
    { difficulty:'Beginner', question:'What is JavaScript?', keywords:['scripting language','web','browser','dynamic','interpreted'], modelAnswer:'JavaScript is a lightweight, interpreted scripting language primarily used to make web pages interactive. It runs in the browser and is also used server-side via Node.js.', example:'Example: `document.querySelector("button").onclick = () => alert("Hello!");`' },
    { difficulty:'Beginner', question:'What is the difference between var, let, and const?', keywords:['var','let','const','scope','hoisting','reassign'], modelAnswer:'`var` is function-scoped and hoisted; `let` is block-scoped and can be reassigned; `const` is block-scoped and cannot be reassigned after declaration.', example:'Example: `let x = 5; x = 10;` works, but `const y = 5; y = 10;` throws an error.' },
    { difficulty:'Beginner', question:'What is a closure in JavaScript?', keywords:['closure','inner function','outer scope','lexical','encapsulation'], modelAnswer:'A closure is a function that retains access to variables from its outer (enclosing) function scope even after the outer function has returned.', example:'Example: `function outer(){ let x=10; return function(){ console.log(x); }; } outer()();` logs 10.' },
    { difficulty:'Beginner', question:'What are data types in JavaScript?', keywords:['string','number','boolean','null','undefined','object','symbol','BigInt'], modelAnswer:'JavaScript has 8 data types: String, Number, Boolean, Null, Undefined, Object, Symbol, and BigInt. The first 7 are primitives (or reference in case of Object).', example:'Example: `typeof "hello"` → "string"; `typeof 42` → "number"; `typeof null` → "object" (quirk).' },
    { difficulty:'Beginner', question:'What is the difference between == and ===?', keywords:['equality','strict','type coercion','loose','comparison'], modelAnswer:'`==` performs loose equality with type coercion, while `===` performs strict equality without type coercion — both value AND type must match.', example:'Example: `0 == "0"` is true, but `0 === "0"` is false.' },
    { difficulty:'Beginner', question:'What is the DOM?', keywords:['Document Object Model','HTML','tree','nodes','manipulation'], modelAnswer:'The DOM (Document Object Model) is a programming interface for HTML documents. It represents the page as a tree of nodes that JavaScript can read and manipulate.', example:'Example: `document.getElementById("title").innerText = "Hello";` changes text on the page.' },
    { difficulty:'Beginner', question:'What is an arrow function?', keywords:['arrow','fat arrow','this','concise','ES6'], modelAnswer:'Arrow functions are a concise syntax for writing functions using `=>`. They do not have their own `this` binding, inheriting it from the enclosing scope.', example:'Example: `const add = (a, b) => a + b;` instead of `function add(a,b){ return a+b; }`.' },
    { difficulty:'Beginner', question:'What is the difference between null and undefined?', keywords:['null','undefined','assigned','intentional','uninitialized'], modelAnswer:'`undefined` means a variable has been declared but not yet assigned a value. `null` is an intentional assignment representing "no value".', example:'Example: `let x;` → x is undefined. `let y = null;` → y is explicitly empty.' },
    { difficulty:'Beginner', question:'What is event bubbling in JavaScript?', keywords:['bubbling','propagation','parent','child','event','stopPropagation'], modelAnswer:'Event bubbling is when an event triggered on a child element propagates (bubbles) up to its parent elements. Use `event.stopPropagation()` to prevent it.', example:'Example: Clicking a button inside a div triggers both the button\'s and div\'s click handlers.' },
    { difficulty:'Beginner', question:'What is a callback function?', keywords:['callback','function','argument','asynchronous','higher-order'], modelAnswer:'A callback is a function passed as an argument to another function, to be executed later — often after an async operation completes.', example:'Example: `setTimeout(() => console.log("done"), 1000);` — the arrow function is the callback.' },
    { difficulty:'Beginner', question:'What does the typeof operator return?', keywords:['typeof','string','number','boolean','object','undefined','function'], modelAnswer:'`typeof` returns a string indicating the type of the operand. Common returns: "string", "number", "boolean", "undefined", "object", "function", "symbol".', example:'Example: `typeof []` → "object"; `typeof function(){}` → "function".' },
    { difficulty:'Beginner', question:'What is an array in JavaScript?', keywords:['array','list','index','push','pop','length','ordered'], modelAnswer:'An array is an ordered collection of values (elements) stored under a single variable. Elements are accessed by their numeric index starting from 0.', example:'Example: `const fruits = ["apple","banana"]; fruits[0]` → "apple"; `fruits.push("mango")` adds to end.' },
    { difficulty:'Beginner', question:'What is the use of the console.log() function?', keywords:['console','log','debug','output','browser'], modelAnswer:'`console.log()` prints values to the browser\'s developer console. It is primarily used for debugging — inspecting variable values and tracking program flow.', example:'Example: `console.log("User:", user.name, "Age:", user.age);`' },
    { difficulty:'Beginner', question:'What is JSON?', keywords:['JSON','JavaScript Object Notation','parse','stringify','data exchange'], modelAnswer:'JSON (JavaScript Object Notation) is a lightweight data format for storing and transmitting structured data. It is text-based and both humans and machines can read it easily.', example:'Example: `JSON.stringify({name:"John"})` → \'{"name":"John"}\'; `JSON.parse(\'{"name":"John"}\')` → object.' },
    { difficulty:'Beginner', question:'What is a template literal?', keywords:['template literal','backtick','interpolation','multiline','string'], modelAnswer:'Template literals are string literals using backticks (`) that allow embedded expressions using `${}` and support multi-line strings without escape characters.', example:'Example: `` const msg = `Hello, ${name}! You are ${age} years old.`; ``' },
    { difficulty:'Beginner', question:'How do you declare a function in JavaScript?', keywords:['function declaration','function expression','arrow','syntax','hoisting'], modelAnswer:'Functions can be declared with the `function` keyword (declaration), assigned to a variable (expression), or written as arrow functions. Declarations are hoisted; expressions are not.', example:'Example: `function greet(name){ return "Hi "+name; }` or `const greet = name => "Hi "+name;`' },
    { difficulty:'Beginner', question:'What is the purpose of the return statement?', keywords:['return','value','function','exit','output'], modelAnswer:'The `return` statement ends function execution and specifies the value to be returned to the function caller. A function without return returns `undefined`.', example:'Example: `function square(n){ return n * n; } square(4);` → 16.' },

    // ── Intermediate (17) ──
    { difficulty:'Intermediate', question:'What is the Event Loop in JavaScript?', keywords:['event loop','call stack','queue','asynchronous','non-blocking','microtask','macrotask'], modelAnswer:'The Event Loop monitors the Call Stack and the Callback Queue. When the stack is empty, it pushes the first callback from the queue onto the stack to execute. This is how JS handles async operations without blocking.', example:'Example: setTimeout callbacks go to the macrotask queue; Promises go to the microtask queue (higher priority).' },
    { difficulty:'Intermediate', question:'What are Promises in JavaScript?', keywords:['Promise','resolve','reject','then','catch','pending','fulfilled','rejected'], modelAnswer:'A Promise is an object representing the eventual completion or failure of an async operation. It has three states: pending, fulfilled, and rejected. Use `.then()` and `.catch()` to handle results.', example:'Example: `fetch(url).then(res => res.json()).then(data => console.log(data)).catch(err => console.error(err));`' },
    { difficulty:'Intermediate', question:'What is async/await?', keywords:['async','await','Promise','synchronous','asynchronous','try','catch'], modelAnswer:'`async/await` is syntactic sugar over Promises. Marking a function `async` makes it return a Promise. `await` pauses execution inside the function until the Promise resolves, keeping code readable.', example:'Example: `async function getData(){ try{ const res = await fetch(url); return await res.json(); } catch(e){ console.error(e); } }`' },
    { difficulty:'Intermediate', question:'What is destructuring in JavaScript?', keywords:['destructuring','array','object','extract','variable','ES6'], modelAnswer:'Destructuring allows unpacking values from arrays or properties from objects into distinct variables in a single statement.', example:'Example: `const {name, age} = user;` or `const [first, second] = arr;`' },
    { difficulty:'Intermediate', question:'What is the spread operator?', keywords:['spread','rest','array','object','copy','merge','...'], modelAnswer:'The spread operator (`...`) expands an iterable (array, string) or object into individual elements. Used for copying, merging arrays/objects, and passing arguments.', example:'Example: `const merged = [...arr1, ...arr2];` or `const newObj = {...obj1, ...obj2};`' },
    { difficulty:'Intermediate', question:'What is prototype in JavaScript?', keywords:['prototype','prototype chain','inheritance','__proto__','Object.create'], modelAnswer:'Every JavaScript object has a prototype — a reference to another object from which it inherits properties and methods. This chain of prototypes is called the prototype chain.', example:'Example: `Array.prototype.myMethod = function(){ return "custom"; };` adds a method to all arrays.' },
    { difficulty:'Intermediate', question:'What is the difference between call, apply, and bind?', keywords:['call','apply','bind','this','context','arguments','function'], modelAnswer:'`call` invokes a function with a given `this` and individual arguments. `apply` is the same but takes arguments as an array. `bind` returns a new function with `this` permanently bound.', example:'Example: `greet.call(user, "Hello");` vs `greet.apply(user, ["Hello"]);` vs `const fn = greet.bind(user);`' },
    { difficulty:'Intermediate', question:'What is hoisting in JavaScript?', keywords:['hoisting','var','function','declaration','initialization','scope'], modelAnswer:'Hoisting is JavaScript\'s behavior of moving declarations (not initializations) to the top of their scope before execution. `var` and function declarations are hoisted; `let`/`const` are hoisted but not initialized (Temporal Dead Zone).', example:'Example: `console.log(x); var x = 5;` logs undefined (hoisted). `console.log(y); let y = 5;` throws ReferenceError.' },
    { difficulty:'Intermediate', question:'What are higher-order functions?', keywords:['higher-order','map','filter','reduce','callback','function returns function'], modelAnswer:'Higher-order functions are functions that accept other functions as arguments or return functions. Examples include `map`, `filter`, and `reduce`.', example:'Example: `[1,2,3].map(x => x * 2)` → [2,4,6]; `[1,2,3,4].filter(x => x > 2)` → [3,4].' },
    { difficulty:'Intermediate', question:'What is the difference between map and forEach?', keywords:['map','forEach','return','array','iteration','transform'], modelAnswer:'`map` returns a new array with transformed elements; `forEach` iterates over elements without returning a new array. Use `map` when you need the result; `forEach` for side effects.', example:'Example: `[1,2,3].map(x => x*2)` → [2,4,6], but `[1,2,3].forEach(x => x*2)` → undefined.' },
    { difficulty:'Intermediate', question:'What is a pure function?', keywords:['pure function','side effects','deterministic','immutable','functional'], modelAnswer:'A pure function always returns the same output for the same input and has no side effects (doesn\'t modify external state). They are predictable and easy to test.', example:'Example: `const add = (a,b) => a+b;` is pure. `let count=0; const increment = () => ++count;` is impure.' },
    { difficulty:'Intermediate', question:'What is a generator function?', keywords:['generator','yield','iterator','function*','next','lazy evaluation'], modelAnswer:'A generator function (marked with `function*`) can pause execution and resume later using `yield`. Each call to `.next()` runs until the next `yield` and returns `{value, done}`.', example:'Example: `function* count(){ yield 1; yield 2; yield 3; } const gen = count(); gen.next();` → {value:1, done:false}.' },
    { difficulty:'Intermediate', question:'What is a WeakMap and when would you use it?', keywords:['WeakMap','garbage collection','weak reference','memory','key'], modelAnswer:'A WeakMap holds weak references to objects as keys — if no other reference to the key exists, it can be garbage-collected. Used for storing private data associated with objects without preventing GC.', example:'Example: Storing DOM element metadata: `const meta = new WeakMap(); meta.set(element, {clicked: true});`' },
    { difficulty:'Intermediate', question:'What is the module system in JavaScript (ES Modules)?', keywords:['import','export','module','ES6','scope','namespace'], modelAnswer:'ES Modules allow you to split code into separate files using `export` and `import`. Each module has its own scope, preventing global namespace pollution.', example:'Example: `// math.js: export const add = (a,b) => a+b;` and `// app.js: import {add} from "./math.js";`' },
    { difficulty:'Intermediate', question:'What is memoization?', keywords:['memoization','cache','performance','pure function','optimization'], modelAnswer:'Memoization is an optimization technique that caches the results of expensive function calls and returns the cached result when the same inputs are given again.', example:'Example: `const memo = {}; function fib(n){ if(memo[n]) return memo[n]; return memo[n] = n <= 1 ? n : fib(n-1)+fib(n-2); }`' },
    { difficulty:'Intermediate', question:'What are Symbol types used for?', keywords:['Symbol','unique','identifier','property key','well-known'], modelAnswer:'`Symbol` creates a guaranteed unique value, often used as unique property keys on objects to avoid naming collisions, especially in large codebases or libraries.', example:'Example: `const id = Symbol("id"); const user = {[id]: 123}; user[id]` → 123.' },
    { difficulty:'Intermediate', question:'What is optional chaining (?.) in JavaScript?', keywords:['optional chaining','?.','null','undefined','safe access','short-circuit'], modelAnswer:'Optional chaining (`?.`) safely accesses nested object properties without throwing an error if an intermediate value is null or undefined — it returns `undefined` instead.', example:'Example: `user?.address?.city` → returns city if it exists, or undefined without throwing.' },

    // ── Advanced (16) ──
    { difficulty:'Advanced', question:'Explain the concept of JavaScript engine execution (V8).', keywords:['V8','JIT','compilation','bytecode','abstract syntax tree','optimization','garbage collection'], modelAnswer:'The V8 engine parses JS into an AST, compiles it to bytecode via Ignition interpreter, then optimizes hot code paths with the TurboFan JIT compiler. It also manages memory via garbage collection.', example:'Example: Repeated calls to a function cause V8 to optimize it with type assumptions.' },
    { difficulty:'Advanced', question:'What is the difference between microtasks and macrotasks?', keywords:['microtask','macrotask','event loop','Promise','setTimeout','priority','queue'], modelAnswer:'Microtasks (Promises, queueMicrotask) run immediately after the current task before the browser renders or runs the next macrotask. Macrotasks (setTimeout, setInterval, I/O) wait in the task queue.', example:'Example: `Promise.resolve().then(() => console.log("micro"));  setTimeout(() => console.log("macro"), 0);` — "micro" always logs first.' },
    { difficulty:'Advanced', question:'What is memory management and garbage collection in JS?', keywords:['garbage collection','mark and sweep','reference counting','memory leak','heap','weak reference'], modelAnswer:'JavaScript uses automatic garbage collection — primarily mark-and-sweep — to reclaim memory no longer reachable from roots. Memory leaks occur when references are unintentionally retained.', example:'Example: Event listeners not removed after DOM element deletion cause memory leaks.' },
    { difficulty:'Advanced', question:'What is the Proxy object?', keywords:['Proxy','handler','trap','get','set','intercept','meta-programming'], modelAnswer:'A `Proxy` wraps an object and intercepts operations (get, set, delete, etc.) using "traps". It enables meta-programming — building reactive systems, validation layers, or virtual objects.', example:'Example: `const p = new Proxy({}, { get: (t,k) => k in t ? t[k] : "default" });`' },
    { difficulty:'Advanced', question:'What is tail call optimization?', keywords:['tail call','optimization','recursion','stack overflow','TCO','ES6'], modelAnswer:'Tail call optimization (TCO) allows the engine to reuse the current stack frame for recursive tail calls (where the recursive call is the last operation) instead of adding a new frame, preventing stack overflow.', example:'Example: `function factorial(n, acc=1){ return n<=1 ? acc : factorial(n-1, n*acc); }` — tail recursive.' },
    { difficulty:'Advanced', question:'Explain how the JavaScript module bundler works (Webpack/Vite).', keywords:['bundler','Webpack','Vite','dependency graph','tree shaking','code splitting','module'], modelAnswer:'Bundlers analyze the entry point, build a dependency graph of all imports, transform/transpile files, and package them into optimized output bundles. Vite uses native ES modules in dev and Rollup for prod.', example:'Example: Vite serves files unbundled in dev (fast), then uses Rollup to create optimized chunks for production.' },
    { difficulty:'Advanced', question:'What are Web Workers?', keywords:['Web Worker','thread','background','postMessage','main thread','parallel'], modelAnswer:'Web Workers run scripts in background threads separate from the main UI thread, enabling CPU-intensive tasks without blocking the UI. They communicate via `postMessage` and `onmessage`.', example:'Example: Using a worker for image processing, sorting large arrays, or encryption without freezing the UI.' },
    { difficulty:'Advanced', question:'What is the difference between shallow and deep copy?', keywords:['shallow copy','deep copy','reference','nested','spread','structuredClone'], modelAnswer:'Shallow copy copies the top-level properties; nested objects are still shared by reference. Deep copy creates fully independent copies of all levels. Use `structuredClone()` or JSON trick for deep copy.', example:'Example: `const shallow = {...obj};` — nested objects shared. `const deep = structuredClone(obj);` — fully independent.' },
    { difficulty:'Advanced', question:'What is reactive programming and how is it used in JS?', keywords:['reactive','observable','RxJS','stream','subscribe','event-driven'], modelAnswer:'Reactive programming treats data as streams of values over time. Libraries like RxJS provide `Observable` — you subscribe to streams and react to emitted values using operators like `map`, `filter`, `mergeMap`.', example:'Example: `fromEvent(button, "click").pipe(debounceTime(300)).subscribe(e => console.log(e));`' },
    { difficulty:'Advanced', question:'What is a service worker?', keywords:['service worker','offline','cache','PWA','intercept','fetch','background sync'], modelAnswer:'A service worker is a script that runs in the background, separate from the web page. It intercepts network requests, enables offline caching, push notifications, and background sync for PWAs.', example:'Example: Caching app shell files in service worker install event for offline support.' },
    { difficulty:'Advanced', question:'What design patterns are commonly used in JavaScript?', keywords:['design pattern','singleton','observer','factory','module','decorator','MVC'], modelAnswer:'Common JS patterns: Singleton (one instance), Observer (pub/sub events), Factory (create objects), Module (encapsulate state), Decorator (extend behavior), MVC/MVVM (architecture).', example:'Example: Event emitters use the Observer pattern; React components use the Composite pattern.' },
    { difficulty:'Advanced', question:'What is tree shaking?', keywords:['tree shaking','dead code','bundle size','ES modules','Rollup','Webpack','static analysis'], modelAnswer:'Tree shaking is a dead code elimination technique used by bundlers. It statically analyzes ES module imports and removes exports that are never used, reducing bundle size.', example:'Example: Importing only `{useState}` from React ensures only that function is bundled if the tool supports tree shaking.' },
    { difficulty:'Advanced', question:'How does JavaScript handle concurrency with a single thread?', keywords:['single thread','concurrency','event loop','async','non-blocking','IO','callback'], modelAnswer:'JS is single-threaded but handles concurrency through async I/O and the event loop. Blocking operations (network, disk) are offloaded to the browser/Node APIs; callbacks are queued and executed when the stack is clear.', example:'Example: A `fetch()` call doesn\'t block the thread — the browser handles the network request and pushes the callback onto the queue when done.' },
    { difficulty:'Advanced', question:'What is the Temporal Dead Zone (TDZ)?', keywords:['TDZ','temporal dead zone','let','const','hoisting','ReferenceError','block scope'], modelAnswer:'The TDZ is the period between entering a block scope and the actual variable declaration where accessing a `let` or `const` variable throws a `ReferenceError`, even though the declaration is hoisted.', example:'Example: `{ console.log(x); let x = 5; }` throws ReferenceError — x exists but is in TDZ.' },
    { difficulty:'Advanced', question:'What is the difference between composition and inheritance in JS?', keywords:['composition','inheritance','prototype','mixins','favor composition','flexibility'], modelAnswer:'Inheritance creates an "is-a" relationship via prototype chains; composition creates a "has-a" relationship by combining smaller, focused objects/functions. The principle "favor composition over inheritance" promotes flexibility.', example:'Example: Instead of `class Dog extends Animal`, compose: `const dog = {...animalBehavior, ...canBehavior, bark(){}};`' },
    { difficulty:'Advanced', question:'How do you implement debounce and throttle?', keywords:['debounce','throttle','performance','delay','rate-limit','event optimization'], modelAnswer:'Debounce delays execution until after a quiet period (no more calls). Throttle limits execution to at most once per time interval. Both optimize performance for high-frequency events like scroll/resize/input.', example:'Example: `const debounce = (fn,ms) => { let t; return (...args) => { clearTimeout(t); t = setTimeout(()=>fn(...args), ms); }; };`' },
  ],

  // ══════════════════════════════════════════════════════════════
  // PYTHON  —  50 questions
  // ══════════════════════════════════════════════════════════════
  Python: [
    // ── Beginner (17) ──
    { difficulty:'Beginner', question:'What is Python?', keywords:['interpreted','high-level','general-purpose','dynamic typing','readable'], modelAnswer:'Python is a high-level, interpreted, general-purpose programming language known for its simple, readable syntax. It supports multiple paradigms: procedural, object-oriented, and functional.', example:'Example: `print("Hello, World!")` — one line is all it takes.' },
    { difficulty:'Beginner', question:'What is the difference between a list and a tuple in Python?', keywords:['list','tuple','mutable','immutable','ordered','brackets'], modelAnswer:'Lists are mutable (can be changed) and use square brackets `[]`. Tuples are immutable (cannot be changed after creation) and use parentheses `()`. Tuples are faster and can be used as dictionary keys.', example:'Example: `my_list = [1,2,3]; my_list[0] = 99` works. `my_tuple = (1,2,3); my_tuple[0] = 99` throws TypeError.' },
    { difficulty:'Beginner', question:'What is a dictionary in Python?', keywords:['dictionary','key','value','hash','mutable','unordered'], modelAnswer:'A dictionary is an unordered collection of key-value pairs. Keys must be unique and immutable. Dictionaries are mutable and optimized for fast lookups by key.', example:'Example: `person = {"name": "Alice", "age": 25}; person["name"]` → "Alice".' },
    { difficulty:'Beginner', question:'What is a Python function?', keywords:['def','function','parameter','return','call','reusable'], modelAnswer:'A function is a block of reusable code defined with the `def` keyword. It can accept parameters and optionally return a value. Functions promote code reuse and modularity.', example:'Example: `def greet(name): return f"Hello, {name}!" ; greet("Alice")` → "Hello, Alice!"' },
    { difficulty:'Beginner', question:'What are Python list comprehensions?', keywords:['list comprehension','concise','loop','filter','expression','transform'], modelAnswer:'List comprehensions provide a concise way to create lists using a single line expression with an optional condition: `[expression for item in iterable if condition]`.', example:'Example: `squares = [x**2 for x in range(10) if x % 2 == 0]` → [0, 4, 16, 36, 64].' },
    { difficulty:'Beginner', question:'What is the difference between == and is in Python?', keywords:['==','is','equality','identity','value','object'], modelAnswer:'`==` checks value equality (are values the same?). `is` checks identity (are they the exact same object in memory?). Always use `==` for value comparison; use `is` only for None checks.', example:'Example: `a = [1,2]; b = [1,2]; a == b` → True; `a is b` → False (different objects).' },
    { difficulty:'Beginner', question:'What is indentation in Python?', keywords:['indentation','whitespace','block','syntax','4 spaces'], modelAnswer:'Python uses indentation (whitespace) to define code blocks instead of braces. Consistent indentation (4 spaces recommended) is mandatory — incorrect indentation causes an IndentationError.', example:'Example: `if True:\n    print("yes")  # must be indented`' },
    { difficulty:'Beginner', question:'What are Python modules?', keywords:['module','import','package','namespace','library','reuse'], modelAnswer:'A module is a file containing Python code (functions, classes, variables) that can be imported and reused in other programs using the `import` statement.', example:'Example: `import math; math.sqrt(16)` → 4.0. `from os import path; path.exists("file.txt")`' },
    { difficulty:'Beginner', question:'What are *args and **kwargs?', keywords:['args','kwargs','variable arguments','packing','unpacking','arbitrary'], modelAnswer:'`*args` allows a function to accept any number of positional arguments as a tuple. `**kwargs` allows any number of keyword arguments as a dictionary.', example:'Example: `def show(*args, **kwargs): print(args, kwargs); show(1,2, name="Alice")` → (1,2) {"name":"Alice"}.' },
    { difficulty:'Beginner', question:'What is a lambda function in Python?', keywords:['lambda','anonymous','one-line','expression','functional'], modelAnswer:'A lambda is a small anonymous function defined in one line using the `lambda` keyword. It can take any number of arguments but has only one expression.', example:'Example: `double = lambda x: x * 2; double(5)` → 10. Often used with map/filter.' },
    { difficulty:'Beginner', question:'What is the range() function?', keywords:['range','start','stop','step','sequence','loop'], modelAnswer:'`range()` generates an immutable sequence of numbers. It takes `start` (default 0), `stop` (exclusive), and `step` (default 1) parameters. Commonly used in for loops.', example:'Example: `range(0,10,2)` → 0,2,4,6,8. `list(range(5))` → [0,1,2,3,4].' },
    { difficulty:'Beginner', question:'How does exception handling work in Python?', keywords:['try','except','finally','raise','exception','error handling'], modelAnswer:'Python uses `try`/`except` blocks. Code in `try` is executed; if an exception occurs, matching `except` block runs. `finally` always runs. `raise` triggers exceptions manually.', example:'Example: `try: result = 10/0 except ZeroDivisionError: print("Can\'t divide by zero") finally: print("done")`' },
    { difficulty:'Beginner', question:'What is a set in Python?', keywords:['set','unique','unordered','mutable','union','intersection','curly braces'], modelAnswer:'A set is an unordered collection of unique elements. Sets are mutable and support mathematical operations like union, intersection, and difference. Defined with curly braces or `set()`.', example:'Example: `s = {1,2,3,2,1}` → {1,2,3} (duplicates removed). `s.add(4); s.union({5,6})`.' },
    { difficulty:'Beginner', question:'What is string formatting in Python?', keywords:['f-string','format','string interpolation','%','format method'], modelAnswer:'Python supports multiple formatting methods: f-strings (fastest, modern), `.format()`, and `%` operator. F-strings (Python 3.6+) embed expressions directly in string literals.', example:'Example: `name="Alice"; age=25; f"Name: {name}, Age: {age}"` → "Name: Alice, Age: 25".' },
    { difficulty:'Beginner', question:'What are Python decorators?', keywords:['decorator','@','wrapper','higher-order','function modification'], modelAnswer:'A decorator is a function that wraps another function to extend its behavior without modifying it. Used with the `@` syntax, commonly for logging, caching, authentication.', example:'Example: `@property`, `@staticmethod`, or custom: `@login_required` that checks auth before running a view.' },
    { difficulty:'Beginner', question:'What is the difference between append() and extend() for a list?', keywords:['append','extend','list','add','single','multiple'], modelAnswer:'`append()` adds a single element to the end of the list. `extend()` adds all elements from an iterable to the list.', example:'Example: `lst = [1,2]; lst.append([3,4])` → [1,2,[3,4]]. `lst.extend([3,4])` → [1,2,3,4].' },
    { difficulty:'Beginner', question:'What is PEP 8?', keywords:['PEP 8','style guide','convention','naming','indentation','readability'], modelAnswer:'PEP 8 is Python\'s official style guide covering naming conventions (snake_case for functions), indentation (4 spaces), line length (79 chars), and code organization for consistent, readable Python code.', example:'Example: `def calculate_area(radius):` (snake_case) not `def CalculateArea(radius):`.' },

    // ── Intermediate (17) ──
    { difficulty:'Intermediate', question:'What is OOP in Python?', keywords:['class','object','inheritance','encapsulation','polymorphism','__init__','self'], modelAnswer:'OOP organizes code around objects (instances of classes). Python supports all four OOP pillars: Encapsulation (data hiding), Inheritance (reuse), Polymorphism (multiple forms), Abstraction (hiding complexity).', example:'Example: `class Animal: def __init__(self, name): self.name = name; def speak(self): pass` — base class for Dog, Cat.' },
    { difficulty:'Intermediate', question:'What are generators in Python?', keywords:['generator','yield','iterator','lazy','memory-efficient','next()'], modelAnswer:'Generators are functions that use `yield` to return values one at a time, producing items lazily. They are memory-efficient for large datasets because they don\'t store all values in memory at once.', example:'Example: `def count(): i=0; while True: yield i; i+=1` — infinite sequence without memory overflow.' },
    { difficulty:'Intermediate', question:'What is the GIL (Global Interpreter Lock) in Python?', keywords:['GIL','thread','CPython','lock','concurrency','multiprocessing'], modelAnswer:'The GIL is a mutex in CPython that allows only one thread to execute Python bytecode at a time, preventing true multi-threading for CPU-bound tasks. Use `multiprocessing` to bypass it.', example:'Example: For CPU-heavy tasks, use `multiprocessing.Pool` instead of threading to get real parallelism.' },
    { difficulty:'Intermediate', question:'What are magic methods (dunder methods) in Python?', keywords:['dunder','__str__','__repr__','__len__','magic method','special method'], modelAnswer:'Magic methods (double underscore methods) allow classes to implement built-in behaviors. `__init__` (constructor), `__str__` (string representation), `__len__` (length), `__eq__` (equality), etc.', example:'Example: `class Vector: def __add__(self, other): return Vector(self.x+other.x, self.y+other.y)` enables `v1 + v2`.' },
    { difficulty:'Intermediate', question:'What is the difference between deep copy and shallow copy in Python?', keywords:['deep copy','shallow copy','copy module','nested','reference','independent'], modelAnswer:'Shallow copy creates a new object but references the same nested objects. Deep copy creates a completely independent copy of the object and all nested objects. Use the `copy` module.', example:'Example: `import copy; deep = copy.deepcopy(nested_list)` — modifying `deep` doesn\'t affect original.' },
    { difficulty:'Intermediate', question:'What is a context manager and how do you use it?', keywords:['context manager','with','__enter__','__exit__','resource management','file'], modelAnswer:'Context managers manage resources by automatically handling setup and cleanup via `__enter__` and `__exit__` methods. The `with` statement ensures resources are released even if errors occur.', example:'Example: `with open("file.txt") as f: data = f.read()` — file is automatically closed after the block.' },
    { difficulty:'Intermediate', question:'How does Python manage memory?', keywords:['memory management','reference counting','garbage collection','heap','refcount'], modelAnswer:'Python manages memory via reference counting (each object tracks how many references point to it) and a cyclic garbage collector (for circular references). Objects are freed when refcount drops to 0.', example:'Example: `a = [1,2,3]; b = a` → refcount is 2. `del a` → refcount is 1. `del b` → object freed.' },
    { difficulty:'Intermediate', question:'What is the difference between classmethod and staticmethod?', keywords:['classmethod','staticmethod','cls','self','instance','class-level'], modelAnswer:'`@classmethod` receives the class (`cls`) as the first argument and can access/modify class state. `@staticmethod` receives no implicit argument and is essentially a regular function namespaced in the class.', example:'Example: `class Date: @classmethod def from_string(cls, s): ... @staticmethod def validate(s): ...`' },
    { difficulty:'Intermediate', question:'What is multiple inheritance and MRO in Python?', keywords:['multiple inheritance','MRO','Method Resolution Order','C3 linearization','diamond problem'], modelAnswer:'Python supports multiple inheritance (class inherits from multiple parents). MRO (Method Resolution Order) determines which method is called using C3 linearization. `type.mro()` shows the order.', example:'Example: `class C(A,B): pass` — `C.__mro__` → [C, A, B, object]. A\'s methods take priority over B\'s.' },
    { difficulty:'Intermediate', question:'What are Python iterators?', keywords:['iterator','__iter__','__next__','iterable','StopIteration'], modelAnswer:'An iterator is an object implementing `__iter__()` (returns itself) and `__next__()` (returns next value or raises StopIteration). All iterators are iterables; not all iterables are iterators.', example:'Example: `it = iter([1,2,3]); next(it)` → 1; `next(it)` → 2; `next(it)` → 3; `next(it)` raises StopIteration.' },
    { difficulty:'Intermediate', question:'What is functional programming in Python?', keywords:['functional','map','filter','reduce','lambda','pure','immutable'], modelAnswer:'Functional programming treats computation as evaluation of pure functions. Python supports it via `map()`, `filter()`, `reduce()`, lambda, and `functools`. Emphasizes immutability and no side effects.', example:'Example: `from functools import reduce; reduce(lambda a,b: a+b, [1,2,3,4])` → 10.' },
    { difficulty:'Intermediate', question:'What is the asyncio library?', keywords:['asyncio','async','await','coroutine','event loop','concurrent'], modelAnswer:'`asyncio` provides infrastructure for writing concurrent code using coroutines (`async`/`await`). It runs an event loop that manages multiple tasks without threading, ideal for I/O-bound operations.', example:'Example: `async def fetch(): data = await get_data(); return data; asyncio.run(fetch())`' },
    { difficulty:'Intermediate', question:'What are Python property decorators?', keywords:['property','getter','setter','deleter','encapsulation','attribute'], modelAnswer:'`@property` turns a method into a read-only attribute. Combined with `@x.setter` and `@x.deleter`, it enables controlled attribute access with validation, implementing encapsulation cleanly.', example:'Example: `class C: @property def x(self): return self._x; @x.setter def x(self,v): self._x = max(0,v)`' },
    { difficulty:'Intermediate', question:'What are Python metaclasses?', keywords:['metaclass','type','class creation','__new__','__init__','class factory'], modelAnswer:'A metaclass is a class of a class — it defines how classes are created. The default metaclass is `type`. Custom metaclasses can intercept and modify class creation.', example:'Example: `class Meta(type): def __new__(mcs, name, bases, attrs): ... class MyClass(metaclass=Meta): pass`' },
    { difficulty:'Intermediate', question:'What is pickling in Python?', keywords:['pickle','serialize','deserialize','binary','object persistence'], modelAnswer:'Pickling is the process of serializing a Python object to a binary byte stream (using `pickle.dumps()`). Unpickling deserializes it back. Used for saving/loading objects or sending them over networks.', example:'Example: `import pickle; data = pickle.dumps(my_obj); obj = pickle.loads(data)`' },
    { difficulty:'Intermediate', question:'What is the difference between %s and f-strings?', keywords:['f-string','%s','format','performance','readability','Python 3.6'], modelAnswer:'`%s` is the old C-style string formatting. f-strings (Python 3.6+) are faster, more readable, and support any expression inside `{}`. `.format()` is the middle ground.', example:'Example: `f"Hello {name}"` is cleaner and faster than `"Hello %s" % name` or `"Hello {}".format(name)`.' },
    { difficulty:'Intermediate', question:'How do you handle multithreading in Python?', keywords:['threading','Thread','lock','GIL','concurrent','daemon','join'], modelAnswer:'Use the `threading` module to create threads. Due to the GIL, threading is better for I/O-bound tasks. Use `Lock` to prevent race conditions. For CPU tasks, use `multiprocessing` instead.', example:'Example: `t = threading.Thread(target=process_data, args=(data,)); t.start(); t.join()`' },

    // ── Advanced (16) ──
    { difficulty:'Advanced', question:'How does Python\'s import system work internally?', keywords:['import','sys.modules','finder','loader','__import__','package'], modelAnswer:'Python\'s import system searches `sys.modules` cache first, then uses finders (meta path finders → path finders) to locate the module, and loaders to compile and execute it, caching in `sys.modules`.', example:'Example: Custom importlib to load modules from a database or encrypted source.' },
    { difficulty:'Advanced', question:'What are descriptors in Python?', keywords:['descriptor','__get__','__set__','__delete__','property','attribute protocol'], modelAnswer:'Descriptors are objects defining `__get__`, `__set__`, or `__delete__` methods. They power Python\'s attribute access protocol — `property`, `staticmethod`, and `classmethod` are all descriptors.', example:'Example: `class Validator: def __set__(self, obj, value): if not isinstance(value, int): raise TypeError(...)`' },
    { difficulty:'Advanced', question:'What is monkey patching in Python?', keywords:['monkey patching','runtime modification','class','method replacement','testing','mock'], modelAnswer:'Monkey patching is dynamically modifying a class or module at runtime by replacing methods or attributes. Used in testing to mock dependencies, though risky in production code.', example:'Example: `import requests; requests.get = lambda url: MockResponse()` — replacing real network call in tests.' },
    { difficulty:'Advanced', question:'What is the difference between concurrency and parallelism in Python?', keywords:['concurrency','parallelism','asyncio','multiprocessing','threading','GIL','CPU-bound'], modelAnswer:'Concurrency manages multiple tasks overlapping in time (async/threading — good for I/O bound). Parallelism truly runs tasks simultaneously on multiple CPUs (`multiprocessing` — good for CPU bound).', example:'Example: Web scraping 100 URLs → use asyncio (concurrent I/O). Matrix multiplication → use multiprocessing (parallel CPU).' },
    { difficulty:'Advanced', question:'How do you optimize Python code for performance?', keywords:['profiling','cProfile','NumPy','C extensions','Cython','algorithm','data structure'], modelAnswer:'Profile first with `cProfile`/`line_profiler`, then optimize: use built-ins and NumPy for numeric ops, choose efficient data structures (set vs list), use generators, cache with `functools.lru_cache`, consider Cython/C extensions.', example:'Example: `@functools.lru_cache(maxsize=None)` caches Fibonacci results, reducing O(2^n) to O(n).' },
    { difficulty:'Advanced', question:'What is Abstract Base Class (ABC) in Python?', keywords:['ABC','abstract','interface','abstractmethod','contract','subclass'], modelAnswer:'ABCs (`abc` module) define interfaces that subclasses must implement. They use `@abstractmethod` to mark required methods, preventing instantiation of incomplete subclasses.', example:'Example: `class Shape(ABC): @abstractmethod def area(self): pass` — Circle must implement `area()` or it can\'t be instantiated.' },
    { difficulty:'Advanced', question:'What is the __slots__ mechanism?', keywords:['__slots__','memory','attribute','fixed','optimization','instance dict'], modelAnswer:'`__slots__` restricts instance attributes to a fixed set, preventing the default `__dict__` creation per instance. This saves memory when creating many instances of a class.', example:'Example: `class Point: __slots__ = ["x","y"]; def __init__(self,x,y): self.x=x; self.y=y` — saves ~50 bytes vs dict per instance.' },
    { difficulty:'Advanced', question:'What is dataclasses in Python?', keywords:['dataclass','@dataclass','__init__','__repr__','__eq__','boilerplate','field'], modelAnswer:'`@dataclass` (Python 3.7+) auto-generates boilerplate methods (`__init__`, `__repr__`, `__eq__`) based on class-level variable annotations. Reduces repetitive code for data-holding classes.', example:'Example: `@dataclass class User: name:str; age:int; email:str` — auto-gets __init__(self, name, age, email).' },
    { difficulty:'Advanced', question:'Explain the Decorator pattern vs Python decorators.', keywords:['design pattern','decorator pattern','Python decorator','wrap','structural','functional'], modelAnswer:'The GoF Decorator pattern extends object behavior dynamically through composition. Python decorators are a syntactic feature that wraps functions/classes. Python decorators can implement the Decorator pattern.', example:'Example: `@lru_cache` wraps a function to add caching — matching both the syntactic and structural decorator concepts.' },
    { difficulty:'Advanced', question:'What is Cython and when would you use it?', keywords:['Cython','C extension','performance','compile','typed','CPython'], modelAnswer:'Cython is a superset of Python that compiles to C, providing near-C performance. Use it for CPU-intensive Python code that can\'t be vectorized with NumPy. Write `.pyx` files with type annotations.', example:'Example: Image processing loops, NLP tokenizers, physics simulations that are bottlenecked in pure Python.' },
    { difficulty:'Advanced', question:'What are Python type hints and the typing module?', keywords:['type hints','typing','mypy','annotation','static analysis','generic'], modelAnswer:'Type hints (PEP 484) annotate variables and function signatures for static analysis tools like mypy. They don\'t enforce types at runtime but improve IDE support, documentation, and catch bugs early.', example:'Example: `def greet(name: str) -> str: return f"Hello {name}"`. Use `List[int]`, `Optional[str]`, `Dict[str,Any]`.' },
    { difficulty:'Advanced', question:'What is the Observer design pattern and how to implement it in Python?', keywords:['observer','publish-subscribe','event','notify','listener','decoupled'], modelAnswer:'The Observer pattern defines a one-to-many dependency: when one object (subject) changes state, all dependents (observers) are notified automatically. Enables loose coupling.', example:'Example: `class EventBus: _listeners={}; def on(self,e,fn): _listeners[e].append(fn); def emit(self,e,data): [f(data) for f in _listeners[e]]`' },
    { difficulty:'Advanced', question:'What is protocol-based typing (Structural subtyping)?', keywords:['Protocol','structural subtyping','duck typing','mypy','typing_extensions'], modelAnswer:'`Protocol` (PEP 544) enables structural subtyping — if an object has the right methods, it\'s compatible, without explicit inheritance. This formalizes duck typing for static analysis.', example:'Example: `class Drawable(Protocol): def draw(self) -> None: ...` — any class with `.draw()` satisfies this without inheriting.' },
    { difficulty:'Advanced', question:'How do you write thread-safe code in Python?', keywords:['thread-safe','Lock','RLock','queue','atomic','race condition','synchronization'], modelAnswer:'Use `threading.Lock` (or `RLock` for re-entrant) to protect shared mutable state. Use `queue.Queue` for producer-consumer patterns (thread-safe by design). Avoid mutable global state.', example:'Example: `with self.lock: self.shared_counter += 1` — ensures only one thread increments at a time.' },
    { difficulty:'Advanced', question:'What is memory profiling in Python?', keywords:['memory profiling','tracemalloc','memory_profiler','heap','leak','allocation'], modelAnswer:'Use `tracemalloc` (built-in) or `memory_profiler` library to track memory allocations. Identify leaks by comparing snapshots. Common causes: circular references, large caches, global state.', example:'Example: `tracemalloc.start(); code(); snapshot = tracemalloc.take_snapshot(); snapshot.statistics("lineno")`' },
    { difficulty:'Advanced', question:'What is the difference between __new__ and __init__?', keywords:['__new__','__init__','instance creation','singleton','metaclass','cls'], modelAnswer:'`__new__` creates and returns the new instance object (class method, called first). `__init__` initializes the instance after creation (instance method, called second). Override `__new__` for singletons or custom instance creation.', example:'Example: `class Singleton: _instance=None; def __new__(cls): if not cls._instance: cls._instance=super().__new__(cls); return cls._instance`' },
  ],

  // ══════════════════════════════════════════════════════════════
  // DATA STRUCTURES & ALGORITHMS  —  50 questions
  // ══════════════════════════════════════════════════════════════
  'Data Structures and Algorithms': [
    // ── Beginner (17) ──
    { difficulty:'Beginner', question:'What is an array?', keywords:['array','index','fixed size','contiguous','O(1) access','element'], modelAnswer:'An array is a collection of elements stored at contiguous memory locations, all of the same type. Elements are accessed using their index in O(1) time. The size is typically fixed at creation.', example:'Example: `int[] arr = {1,2,3,4,5}; arr[2]` → 3. Access is instant regardless of array size.' },
    { difficulty:'Beginner', question:'What is a linked list?', keywords:['linked list','node','pointer','head','next','dynamic size'], modelAnswer:'A linked list is a linear data structure where each element (node) contains data and a pointer to the next node. Unlike arrays, nodes need not be at contiguous memory locations; size is dynamic.', example:'Example: head → [1|→] → [2|→] → [3|null]. Insertion at front is O(1); access at index is O(n).' },
    { difficulty:'Beginner', question:'What is a stack?', keywords:['stack','LIFO','push','pop','peek','top'], modelAnswer:'A stack is a LIFO (Last In, First Out) data structure. Elements are added (push) and removed (pop) from the top only. Used for function call stack, undo operations, expression parsing.', example:'Example: Browser back button — each page visited is pushed; pressing back pops the current page.' },
    { difficulty:'Beginner', question:'What is a queue?', keywords:['queue','FIFO','enqueue','dequeue','front','rear'], modelAnswer:'A queue is a FIFO (First In, First Out) data structure. Elements are added at the rear (enqueue) and removed from the front (dequeue). Used for task scheduling, BFS, print queues.', example:'Example: Print queue — first document submitted prints first. BFS traversal uses a queue.' },
    { difficulty:'Beginner', question:'What is Big O notation?', keywords:['Big O','time complexity','space complexity','O(n)','O(1)','O(log n)','O(n^2)'], modelAnswer:'Big O notation describes the upper bound on an algorithm\'s time or space complexity as the input size grows. It describes worst-case performance: O(1) constant, O(n) linear, O(log n) logarithmic, O(n²) quadratic.', example:'Example: Linear search = O(n). Binary search = O(log n). Bubble sort = O(n²). Hash lookup = O(1) average.' },
    { difficulty:'Beginner', question:'What is Binary Search?', keywords:['binary search','sorted','divide','mid','O(log n)','search'], modelAnswer:'Binary search finds an element in a sorted array by repeatedly halving the search space. Compare the target with the middle element; if smaller, search left half; if larger, search right half. O(log n) time.', example:'Example: Finding 7 in [1,3,5,7,9,11]: mid=5, 7>5 → search right: [7,9,11], mid=9, 7<9 → search left: [7] found.' },
    { difficulty:'Beginner', question:'What is Bubble Sort?', keywords:['bubble sort','comparison','swap','O(n^2)','stable','pass'], modelAnswer:'Bubble sort repeatedly compares adjacent elements and swaps them if out of order. After each pass, the largest unsorted element "bubbles" to the end. O(n²) time — simple but inefficient for large arrays.', example:'Example: [5,3,1,4,2] → after pass 1: [3,1,4,2,5] → eventually sorted.' },
    { difficulty:'Beginner', question:'What is a hash table?', keywords:['hash table','hash function','key','value','collision','O(1)','bucket'], modelAnswer:'A hash table maps keys to values using a hash function to compute an index (bucket). Supports O(1) average-case insert, delete, and lookup. Collisions handled by chaining or open addressing.', example:'Example: Python dictionaries are hash tables. `d["name"] = "Alice"` — "name" is hashed to a bucket index.' },
    { difficulty:'Beginner', question:'What is recursion?', keywords:['recursion','base case','recursive case','call stack','self-reference'], modelAnswer:'Recursion is a technique where a function calls itself with a smaller input until it reaches a base case (stopping condition). Every recursive solution must have a base case to prevent infinite loops.', example:'Example: `def factorial(n): return 1 if n<=1 else n * factorial(n-1)`. factorial(4) = 4×3×2×1 = 24.' },
    { difficulty:'Beginner', question:'What is a tree data structure?', keywords:['tree','node','root','leaf','parent','child','height','depth'], modelAnswer:'A tree is a hierarchical data structure with a root node, where each node has zero or more child nodes and exactly one parent (except root). Leaves have no children. Height = longest root-to-leaf path.', example:'Example: File system folders form a tree. DOM (HTML document) is a tree structure.' },
    { difficulty:'Beginner', question:'What is a Binary Tree?', keywords:['binary tree','at most two children','left','right','parent'], modelAnswer:'A binary tree is a tree where each node has at most two children: left and right. Not necessarily ordered. Special cases: full binary tree (all nodes have 0 or 2 children), complete binary tree (all levels filled except possibly last).', example:'Example: Expression trees for `(3+5)×2` have * at root, + as left child, 2 as right child of *.' },
    { difficulty:'Beginner', question:'What is the difference between BFS and DFS?', keywords:['BFS','DFS','breadth-first','depth-first','queue','stack','graph traversal'], modelAnswer:'BFS (Breadth-First Search) explores all neighbors at the current depth before going deeper — uses a queue. DFS (Depth-First Search) explores as far as possible before backtracking — uses a stack (or recursion).', example:'Example: BFS finds the shortest path in an unweighted graph. DFS is used for topological sort, detecting cycles.' },
    { difficulty:'Beginner', question:'What is a Binary Search Tree (BST)?', keywords:['BST','left smaller','right larger','search','insert','delete'], modelAnswer:'A BST is a binary tree where for every node, all values in the left subtree are smaller and all values in the right subtree are larger. Enables O(log n) search for balanced trees.', example:'Example: Inserting 5,3,7,1,4 → root=5; 3<5→left; 7>5→right; 1<3→3\'s left; 4>3 and <5→3\'s right.' },
    { difficulty:'Beginner', question:'What is a graph data structure?', keywords:['graph','vertex','edge','directed','undirected','weighted','adjacency'], modelAnswer:'A graph consists of vertices (nodes) connected by edges. Can be directed (edges have direction) or undirected. Can be weighted (edges have costs) or unweighted. Represented via adjacency list or matrix.', example:'Example: Social network (vertices=users, edges=friendships), road network (vertices=cities, edges=roads with distances).' },
    { difficulty:'Beginner', question:'What is space complexity?', keywords:['space complexity','memory','auxiliary','O(n)','O(1)','Big O'], modelAnswer:'Space complexity measures the amount of memory an algorithm uses relative to input size. Includes auxiliary space (extra memory used beyond input). Aim to minimize both time and space complexity.', example:'Example: In-place sorting (bubble sort) uses O(1) extra space. Merge sort uses O(n) extra space for the temporary array.' },
    { difficulty:'Beginner', question:'What is a palindrome check algorithm?', keywords:['palindrome','reverse','two pointers','string','symmetric'], modelAnswer:'Check if a string is a palindrome by comparing characters from both ends moving inward (two-pointer approach) or by comparing the string with its reverse.', example:'Example: "racecar" → compare r+r, a+a, c+c, middle e — all match → palindrome. "hello" → h≠o → not palindrome.' },
    { difficulty:'Beginner', question:'What is the difference between linear and binary search?', keywords:['linear search','binary search','O(n)','O(logn)','sorted','unsorted'], modelAnswer:'Linear search checks each element one by one — O(n), works on unsorted arrays. Binary search divides sorted array in half each step — O(log n), requires sorted array. Binary is much faster for large datasets.', example:'Example: Searching in 1M elements: linear search = 1M steps worst case; binary search = only 20 steps.' },

    // ── Intermediate (17) ──
    { difficulty:'Intermediate', question:'What is dynamic programming?', keywords:['dynamic programming','memoization','tabulation','overlapping subproblems','optimal substructure'], modelAnswer:'Dynamic programming solves problems by breaking them into overlapping subproblems, solving each once, and storing results. Uses memoization (top-down) or tabulation (bottom-up).', example:'Example: Fibonacci with DP: `dp[i] = dp[i-1] + dp[i-2]`. Reduces O(2^n) to O(n) time.' },
    { difficulty:'Intermediate', question:'What is a heap data structure?', keywords:['heap','min-heap','max-heap','priority queue','heapify','O(log n)'], modelAnswer:'A heap is a complete binary tree satisfying the heap property: in a max-heap, parent ≥ children; in a min-heap, parent ≤ children. Used to implement priority queues. Insert/delete = O(log n).', example:'Example: Min-heap: root is always the minimum element. `heapq.heappush(heap, val)` in Python.' },
    { difficulty:'Intermediate', question:'What is Merge Sort?', keywords:['merge sort','divide and conquer','O(n log n)','stable','merge','recursive'], modelAnswer:'Merge sort divides the array in half recursively until single elements, then merges sorted halves. Time O(n log n), space O(n). Stable sort — preserves order of equal elements.', example:'Example: [38,27,43,3] → split → merge sorted halves → [3,27,38,43].' },
    { difficulty:'Intermediate', question:'What is Quick Sort?', keywords:['quick sort','pivot','partition','O(n log n)','in-place','average','worst case O(n^2)'], modelAnswer:'Quick sort selects a pivot, partitions the array into elements smaller and larger than pivot, and recursively sorts each partition. Average O(n log n), worst O(n²). In-place sorting.', example:'Example: Pivot=5, [3,7,1,5,8,2] → [3,1,2] + [5] + [7,8] → recursively sort each partition.' },
    { difficulty:'Intermediate', question:'What is a trie (prefix tree)?', keywords:['trie','prefix','autocomplete','dictionary','O(m)','word search'], modelAnswer:'A trie is a tree where each node represents a character. Words are stored as paths from root to leaf. Used for autocomplete, spell-check, prefix search. Search/insert = O(m) where m is word length.', example:'Example: Storing "cat", "car", "card" — they share the "ca" prefix node, branching at "t" vs "r".' },
    { difficulty:'Intermediate', question:'What is a balanced BST and give examples?', keywords:['balanced BST','AVL tree','Red-Black tree','height','O(log n)','rotation'], modelAnswer:'A balanced BST maintains height O(log n) to ensure search/insert/delete stay O(log n). AVL trees maintain strict balance (height difference ≤1). Red-Black trees maintain looser balance with color properties.', example:'Example: Java\'s `TreeMap` and `TreeSet` use Red-Black trees. Python\'s `sortedcontainers` uses B-trees.' },
    { difficulty:'Intermediate', question:'What is a sliding window technique?', keywords:['sliding window','subarray','O(n)','two pointers','window size','optimization'], modelAnswer:'The sliding window technique maintains a window of elements and slides it across the array, adding new elements and removing old ones. Converts brute-force O(n²) nested loops to O(n) for many substring/subarray problems.', example:'Example: Maximum sum of k consecutive elements: maintain running sum, slide window right (+new, -old element).' },
    { difficulty:'Intermediate', question:'What is topological sorting?', keywords:['topological sort','DAG','directed acyclic graph','dependency','Kahn','DFS'], modelAnswer:'Topological sorting linearly orders vertices of a DAG such that for every directed edge u→v, u comes before v. Used for task scheduling, build systems, course prerequisites. Works only on DAGs.', example:'Example: Build dependencies: if A depends on B and C, topological order ensures B,C are built before A.' },
    { difficulty:'Intermediate', question:'What is Dijkstra\'s algorithm?', keywords:["Dijkstra's",'shortest path','weighted','greedy','priority queue','non-negative'], modelAnswer:'Dijkstra\'s finds the shortest path from a source node to all other nodes in a weighted graph with non-negative edges. Uses a min-heap (priority queue) to greedily pick the next closest unvisited node. O((V+E) log V).', example:'Example: Google Maps routing uses variants of Dijkstra\'s to find fastest routes.' },
    { difficulty:'Intermediate', question:'What is the two-pointer technique?', keywords:['two pointers','left','right','sorted','O(n)','pair sum'], modelAnswer:'The two-pointer technique uses two pointers moving from different ends (or at different speeds) to solve array/string problems in O(n) instead of O(n²). Works great on sorted arrays.', example:'Example: Finding a pair summing to target in sorted array: left=0, right=end; if sum too high, right--; too low, left++.' },
    { difficulty:'Intermediate', question:'What is Kadane\'s algorithm?', keywords:['Kadane','maximum subarray','dynamic programming','O(n)','sum','contiguous'], modelAnswer:'Kadane\'s algorithm finds the maximum sum contiguous subarray in O(n) time. Track `current_max` (include current element or start fresh) and `global_max` (best seen so far).', example:'Example: `[-2,1,-3,4,-1,2,1,-5,4]` → max subarray is [4,-1,2,1] = 6.' },
    { difficulty:'Intermediate', question:'What is graph cycle detection?', keywords:['cycle detection','DFS','Union-Find','visited','back edge','directed','undirected'], modelAnswer:'For undirected graphs: DFS with visited set; a cycle exists if we visit an already-visited non-parent node. For directed: use DFS with recursion stack; Union-Find also works for undirected.', example:'Example: Detecting deadlocks in OS resource allocation graphs uses cycle detection.' },
    { difficulty:'Intermediate', question:'What is memoization vs tabulation?', keywords:['memoization','tabulation','top-down','bottom-up','cache','DP'], modelAnswer:'Memoization (top-down DP): start from the original problem, recurse, and cache results as you go. Tabulation (bottom-up DP): fill a table from smallest subproblems up to the original. Both achieve optimal complexity.', example:'Example: Fibonacci memoized: `if n in memo: return memo[n]`. Tabulated: `dp[i] = dp[i-1]+dp[i-2]`.' },
    { difficulty:'Intermediate', question:'What is a union-find (disjoint set) data structure?', keywords:['union-find','disjoint set','union','find','path compression','rank'], modelAnswer:'Union-Find tracks a set of elements partitioned into non-overlapping subsets. `find()` returns the root of an element\'s component; `union()` merges two components. Path compression and union by rank give near O(1) amortized.', example:'Example: Krusal\'s MST algorithm, detecting connected components, network connectivity queries.' },
    { difficulty:'Intermediate', question:'What is a deque (double-ended queue)?', keywords:['deque','double-ended','O(1)','front','back','sliding window maximum'], modelAnswer:'A deque allows O(1) insertion and deletion from both ends. Used for sliding window maximum problems, palindrome checking, and implementing stacks and queues simultaneously.', example:'Example: Python `collections.deque` — `d.append(x)`, `d.appendleft(x)`, `d.pop()`, `d.popleft()`.' },
    { difficulty:'Intermediate', question:'What are common graph representations?', keywords:['adjacency list','adjacency matrix','edge list','graph representation','space','time'], modelAnswer:'Adjacency list: list of neighbors per vertex — O(V+E) space, O(degree) neighbor traversal. Adjacency matrix: 2D boolean matrix — O(V²) space, O(1) edge lookup. Edge list: list of edges — simple but slow.', example:'Example: Social network with billions of users uses adjacency list (sparse). Flight routing between few airports uses matrix (dense).' },
    { difficulty:'Intermediate', question:'What is an LRU Cache and how do you implement it?', keywords:['LRU','Least Recently Used','cache eviction','doubly linked list','hash map','O(1)'], modelAnswer:'LRU Cache evicts the least recently used item when full. Implement with a hash map (O(1) lookup) + doubly linked list (O(1) order tracking). Move accessed node to head; evict tail.', example:'Example: `get(key)` → find in map, move to front, return value. `put(key,val)` → add to front, evict tail if over capacity.' },

    // ── Advanced (16) ──
    { difficulty:'Advanced', question:'What is the A* search algorithm?', keywords:['A*','heuristic','f(n)','g(n)','h(n)','shortest path','informed search'], modelAnswer:'A* is an informed graph search algorithm that finds the shortest path using f(n) = g(n) + h(n), where g(n) is the cost from start and h(n) is the heuristic estimate to goal. Optimal if heuristic is admissible (never overestimates).', example:'Example: Pathfinding in games using Manhattan distance heuristic to navigate grids efficiently.' },
    { difficulty:'Advanced', question:'What is a Segment Tree?', keywords:['segment tree','range query','update','O(log n)','sum','min','max'], modelAnswer:'A segment tree is a tree data structure for efficient range queries (sum, min, max) and point updates in O(log n). Stores aggregate information about ranges of an array. Space O(n).', example:'Example: Range sum query: `query(l, r)` returns sum of elements from index l to r in O(log n).' },
    { difficulty:'Advanced', question:'What is a Fenwick Tree (Binary Indexed Tree)?', keywords:['Fenwick tree','BIT','prefix sum','O(log n)','update','query'], modelAnswer:'A Fenwick Tree (BIT) supports prefix sum queries and point updates in O(log n) time with O(n) space. Simpler to implement than a segment tree for prefix sums.', example:'Example: `update(i, delta)` adds delta to position i; `query(i)` returns prefix sum 1..i. Used in competitive programming.' },
    { difficulty:'Advanced', question:'What is the Bellman-Ford algorithm?', keywords:['Bellman-Ford','shortest path','negative edges','negative cycle','V-1 relaxations'], modelAnswer:'Bellman-Ford finds shortest paths from a source with negative edge weights (unlike Dijkstra). Runs V-1 relaxations on all edges; detects negative cycles on the V-th relaxation. O(VE) time.', example:'Example: Currency arbitrage detection — negative cycle in exchange rate graph means profit opportunity.' },
    { difficulty:'Advanced', question:'What is Floyd-Warshall algorithm?', keywords:['Floyd-Warshall','all-pairs','shortest path','O(V^3)','dynamic programming'], modelAnswer:'Floyd-Warshall finds shortest paths between ALL pairs of vertices using DP. For each intermediate vertex k, update `dist[i][j] = min(dist[i][j], dist[i][k]+dist[k][j])`. O(V³) time, O(V²) space.', example:'Example: Used when you need shortest paths between all city pairs in a small network.' },
    { difficulty:'Advanced', question:'What is a Red-Black Tree?', keywords:['Red-Black tree','self-balancing','O(log n)','rotation','color','insertion'], modelAnswer:'A Red-Black Tree is a self-balancing BST where each node is colored red or black with rules ensuring the tree stays balanced: root is black, red nodes have black children, all paths to leaves have equal black-height.', example:'Example: Java\'s TreeMap, C++ std::map, Linux kernel\'s CFS scheduler all use Red-Black Trees.' },
    { difficulty:'Advanced', question:'What is the Knuth-Morris-Pratt (KMP) algorithm?', keywords:['KMP','string matching','O(n+m)','failure function','prefix','pattern'], modelAnswer:'KMP finds all occurrences of a pattern in a text in O(n+m) time. Precomputes a failure function (longest proper prefix that is also a suffix) to avoid redundant comparisons on mismatch.', example:'Example: Searching for "ABAB" in "ABABCABABC" — KMP avoids resetting to start on each mismatch.' },
    { difficulty:'Advanced', question:'What is Manacher\'s algorithm?', keywords:["Manacher's",'palindrome','O(n)','longest palindromic substring','expand'], modelAnswer:'Manacher\'s algorithm finds the longest palindromic substring in O(n) time. It uses previously computed palindrome extents to avoid redundant expansion, transforming the string to handle even/odd lengths uniformly.', example:'Example: Finding longest palindrome in "babad" → "bab" or "aba" — Manacher\'s does this in O(n).' },
    { difficulty:'Advanced', question:'What is the Maximum Flow problem?', keywords:['max flow','Ford-Fulkerson','Edmonds-Karp','augmenting path','capacity','min cut'], modelAnswer:'Max flow finds the maximum flow from source to sink in a capacity-constrained network. Ford-Fulkerson uses augmenting paths (BFS in Edmonds-Karp for O(VE²)). Min-cut = max-flow (max-flow min-cut theorem).', example:'Example: Bipartite matching, network routing, hospital-organ donor matching use max flow.' },
    { difficulty:'Advanced', question:'What is a Suffix Array?', keywords:['suffix array','suffix','lexicographic','O(n log n)','string','LCP'], modelAnswer:'A suffix array is a sorted array of all suffixes of a string. Combined with an LCP (Longest Common Prefix) array, enables O(n log n) construction and efficient substring search, pattern matching, and string comparison.', example:'Example: For "banana": suffixes sorted → ["a","ana","anana","banana","na","nana"] — enables binary search for patterns.' },
    { difficulty:'Advanced', question:'What is the Traveling Salesman Problem (TSP)?', keywords:['TSP','NP-hard','Hamiltonian cycle','brute force','dynamic programming','bitmask'], modelAnswer:'TSP finds the shortest route visiting all cities exactly once and returning to start. NP-hard — exact solution via DP with bitmask is O(2^n × n). Approximation algorithms (like Christofides) give near-optimal in polynomial time.', example:'Example: `dp[mask][i]` = min cost to visit cities in mask ending at city i. Transition: `dp[mask|(1<<j)][j] = min(...)`' },
    { difficulty:'Advanced', question:'What is B-Tree and why is it used in databases?', keywords:['B-tree','database','disk','balanced','order','block','index'], modelAnswer:'A B-Tree is a self-balancing m-way search tree designed for disk storage. Each node can hold multiple keys and children, matching disk block sizes. Enables O(log n) search with minimal disk reads. Used in database indexes.', example:'Example: MySQL InnoDB uses B+ Trees (all data in leaves) for primary and secondary indexes.' },
    { difficulty:'Advanced', question:'What is amortized analysis?', keywords:['amortized','average','worst case','aggregate','accounting','potential','O(1) amortized'], modelAnswer:'Amortized analysis averages the cost of operations over a sequence of operations, smoothing out occasional expensive operations. Methods: aggregate (total/n), accounting (credits), potential method.', example:'Example: Dynamic array doubling — O(n) resize happens rarely; amortized insert cost = O(1). Stack operations in various algorithms.' },
    { difficulty:'Advanced', question:'What is the difference between P, NP, NP-hard, and NP-complete?', keywords:['P','NP','NP-hard','NP-complete','polynomial','decidable','reduction'], modelAnswer:'P: solvable in polynomial time. NP: verifiable in polynomial time. NP-hard: at least as hard as all NP problems (may not be in NP). NP-complete: NP ∩ NP-hard. Most believe P≠NP but unproven.', example:'Example: TSP, 3-SAT, Graph Coloring are NP-complete. Sorting is P. Integer factorization is in NP but not known to be NP-complete.' },
    { difficulty:'Advanced', question:'What are approximation algorithms?', keywords:['approximation','NP-hard','ratio','greedy','polynomial','near-optimal'], modelAnswer:'Approximation algorithms find solutions within a provable factor of optimal for NP-hard problems. A ρ-approximation returns a solution at most ρ times the optimal. Trade optimality for polynomial runtime.', example:'Example: Greedy set cover gives O(log n)-approximation. Christofides\' algorithm is a 1.5-approximation for metric TSP.' },
    { difficulty:'Advanced', question:'What is the Z-algorithm for pattern matching?', keywords:['Z-algorithm','string matching','Z-array','O(n+m)','prefix','pattern'], modelAnswer:'The Z-algorithm computes a Z-array where Z[i] = length of the longest substring starting at i that matches a prefix of the string. Pattern search: concatenate pattern+"$"+text, then find Z[i] = |pattern|.', example:'Example: For "aabxaa", Z = [6,1,0,0,2,1] — Z[4]=2 means "aa" matches the prefix "aa".' },
  ],

  // ══════════════════════════════════════════════════════════════
  // JAVA  —  50 questions
  // ══════════════════════════════════════════════════════════════
  Java: [
    // ── Beginner (17) ──
    { difficulty:'Beginner', question:'What is Java?', keywords:['object-oriented','platform independent','JVM','compiled','bytecode','strongly typed'], modelAnswer:'Java is a strongly typed, object-oriented, platform-independent language. Java code compiles to bytecode that runs on the JVM (Java Virtual Machine), enabling "write once, run anywhere" portability.', example:'Example: Android apps, enterprise backends (Spring Boot), and Minecraft are all built with Java.' },
    { difficulty:'Beginner', question:'What is the JVM?', keywords:['JVM','Java Virtual Machine','bytecode','platform','runtime','garbage collection'], modelAnswer:'The JVM (Java Virtual Machine) is a runtime engine that executes Java bytecode. It provides platform independence, memory management (garbage collection), and JIT compilation for performance.', example:'Example: The same .class bytecode file runs on Windows, Mac, and Linux JVMs without recompilation.' },
    { difficulty:'Beginner', question:'What is the difference between JDK, JRE, and JVM?', keywords:['JDK','JRE','JVM','compiler','runtime','development'], modelAnswer:'JVM: runs bytecode. JRE: JVM + runtime libraries (needed to run Java apps). JDK: JRE + compiler (javac) + development tools (needed to write and compile Java code).', example:'Example: A developer needs JDK. An end user just running a Java app needs only JRE.' },
    { difficulty:'Beginner', question:'What is the difference between == and .equals() in Java?', keywords:['==','equals','reference','value','Object','String'], modelAnswer:'`==` compares object references (memory addresses) for objects. `.equals()` compares object content/values. For `String`, always use `.equals()` since two separate string objects with same value will fail `==`.', example:'Example: `String a="hello"; String b=new String("hello"); a==b` → false; `a.equals(b)` → true.' },
    { difficulty:'Beginner', question:'What are the four pillars of OOP in Java?', keywords:['encapsulation','inheritance','polymorphism','abstraction','OOP','class'], modelAnswer:'1. Encapsulation — bundling data+methods, hiding internals. 2. Inheritance — subclass inherits from superclass. 3. Polymorphism — same interface, different implementations. 4. Abstraction — hiding complexity.', example:'Example: `Animal` class → `Dog extends Animal` (inheritance); `Dog.makeSound()` overrides `Animal.makeSound()` (polymorphism).' },
    { difficulty:'Beginner', question:'What is the difference between an abstract class and an interface?', keywords:['abstract class','interface','implements','extends','default method','multiple inheritance'], modelAnswer:'Abstract class: can have constructors, instance variables, concrete methods. Interface: all methods public abstract by default (Java 8+ allows default methods). A class can implement multiple interfaces but extend only one abstract class.', example:'Example: `interface Flyable { void fly(); }` — any class can implement it; `abstract class Vehicle` has shared state.' },
    { difficulty:'Beginner', question:'What is a constructor in Java?', keywords:['constructor','object creation','initialization','no return type','same name'], modelAnswer:'A constructor is a special method with the same name as the class and no return type. It initializes a new object when called with `new`. Java provides a default no-arg constructor if none is defined.', example:'Example: `class Car { String color; Car(String c){ this.color=c; } } Car myCar = new Car("red");`' },
    { difficulty:'Beginner', question:'What is the difference between static and instance members?', keywords:['static','instance','class level','object level','shared','this'], modelAnswer:'Static members belong to the class and are shared across all instances — accessed via class name. Instance members belong to each individual object — accessed via `this` reference.', example:'Example: `Math.PI` is static (shared). `person.name` is instance (different per object).' },
    { difficulty:'Beginner', question:'What are access modifiers in Java?', keywords:['public','private','protected','default','access control','encapsulation'], modelAnswer:'Java has 4 access modifiers: `public` (accessible everywhere), `protected` (same package + subclasses), default/package-private (same package only), `private` (same class only).', example:'Example: Class fields should be `private`; getter/setter methods `public` — enforcing encapsulation.' },
    { difficulty:'Beginner', question:'What is the difference between String, StringBuilder, and StringBuffer?', keywords:['String','StringBuilder','StringBuffer','immutable','mutable','thread-safe','performance'], modelAnswer:'`String` is immutable (new object on each modification — slow for repeated changes). `StringBuilder` is mutable and not thread-safe (fast for single-thread). `StringBuffer` is mutable and thread-safe (slower).', example:'Example: Building a string in a loop: use `StringBuilder` for best performance.' },
    { difficulty:'Beginner', question:'What is an array in Java?', keywords:['array','fixed size','index','type','length','ArrayIndexOutOfBoundsException'], modelAnswer:'A Java array is a fixed-size collection of elements of the same type. Declared with `[]`, accessed by index (0-based). Length is fixed at creation. Throws `ArrayIndexOutOfBoundsException` for invalid index.', example:'Example: `int[] arr = new int[5]; arr[0] = 10; arr.length` → 5.' },
    { difficulty:'Beginner', question:'What is exception handling in Java?', keywords:['try','catch','finally','throw','throws','checked','unchecked'], modelAnswer:'Exception handling uses `try`/`catch`/`finally` blocks. Checked exceptions (compile-time) must be caught or declared with `throws`. Unchecked exceptions (RuntimeException) don\'t require handling.', example:'Example: `try { int r = 10/0; } catch(ArithmeticException e) { System.out.println("Error"); } finally { closeResources(); }`' },
    { difficulty:'Beginner', question:'What are Java Collections?', keywords:['Collection','List','Set','Map','ArrayList','HashMap','LinkedList'], modelAnswer:'Java Collections Framework provides interfaces and implementations for common data structures: `List` (ordered, duplicates), `Set` (unique), `Map` (key-value). Key classes: `ArrayList`, `HashSet`, `HashMap`.', example:'Example: `List<String> names = new ArrayList<>(); names.add("Alice"); names.get(0)` → "Alice".' },
    { difficulty:'Beginner', question:'What is autoboxing and unboxing?', keywords:['autoboxing','unboxing','Integer','int','wrapper class','automatic conversion'], modelAnswer:'Autoboxing automatically converts primitive types to their wrapper class objects (int → Integer). Unboxing converts wrapper objects back to primitives (Integer → int). Java does this automatically.', example:'Example: `List<Integer> list = new ArrayList<>(); list.add(5);` — 5 (int) is autoboxed to Integer.' },
    { difficulty:'Beginner', question:'What is a package in Java?', keywords:['package','namespace','import','organize','access','folder'], modelAnswer:'A package is a namespace that organizes related classes and interfaces. Prevents naming conflicts. Use `import` to access classes from other packages. Corresponds to directory structure.', example:'Example: `package com.company.app;` declares the package. `import java.util.ArrayList;` imports a class.' },
    { difficulty:'Beginner', question:'What is method overloading?', keywords:['overloading','same name','different parameters','compile-time','static polymorphism'], modelAnswer:'Method overloading allows multiple methods with the same name but different parameter lists (number, type, or order) in the same class. Resolved at compile time (static polymorphism).', example:'Example: `int add(int a, int b)`, `double add(double a, double b)`, `int add(int a, int b, int c)` — all valid overloads.' },
    { difficulty:'Beginner', question:'What is method overriding?', keywords:['overriding','subclass','@Override','runtime polymorphism','same signature','virtual'], modelAnswer:'Method overriding allows a subclass to provide a specific implementation of a method already defined in the parent class, with the same signature. Resolved at runtime (dynamic polymorphism). Use `@Override`.', example:'Example: `class Dog extends Animal { @Override void makeSound() { System.out.println("Woof"); } }`' },

    // ── Intermediate (17) ──
    { difficulty:'Intermediate', question:'What is the Java Memory Model?', keywords:['heap','stack','method area','garbage collection','young generation','old generation'], modelAnswer:'JVM memory divides into: Stack (per-thread, local variables/frames), Heap (objects, GC managed - Young/Old gen), Method Area (class metadata), PC registers, Native Method Stack.', example:'Example: `new Object()` allocates on heap. Local variables live on stack and are freed when method returns.' },
    { difficulty:'Intermediate', question:'What is the difference between HashMap and ConcurrentHashMap?', keywords:['HashMap','ConcurrentHashMap','thread-safe','concurrent','segmented locking','null'], modelAnswer:'`HashMap` is not thread-safe. `ConcurrentHashMap` uses segment locking (Java 7) or CAS operations (Java 8+) for thread-safe concurrent access without synchronizing the entire map. `ConcurrentHashMap` doesn\'t allow null keys/values.', example:'Example: Multi-threaded counters: use `ConcurrentHashMap` with `merge()` or `compute()` methods.' },
    { difficulty:'Intermediate', question:'What are Java Generics?', keywords:['generics','type parameter','type safety','compile-time','<T>','wildcard','bounded'], modelAnswer:'Generics allow classes/methods to operate on typed parameters (`<T>`), providing compile-time type safety and eliminating casts. Type information is erased at runtime (type erasure). Wildcards (`?`) add flexibility.', example:'Example: `class Box<T> { T value; Box(T v){ value=v; } }  Box<String> box = new Box<>("Hello");`' },
    { difficulty:'Intermediate', question:'What is the Java Stream API?', keywords:['Stream','filter','map','reduce','collect','lambda','pipeline','lazy'], modelAnswer:'The Stream API (Java 8) provides a declarative, functional approach to process collections. Streams are lazy (operations execute only on terminal operation), chainable, and can be parallelized with `parallelStream()`.', example:'Example: `list.stream().filter(n->n>5).map(n->n*2).collect(Collectors.toList())`' },
    { difficulty:'Intermediate', question:'What is the difference between Comparable and Comparator?', keywords:['Comparable','Comparator','compareTo','compare','natural order','custom order'], modelAnswer:'`Comparable` defines a class\'s natural ordering via `compareTo()` — the class itself is modified. `Comparator` defines external, custom orderings via `compare()` — no modification to original class needed.', example:'Example: `Collections.sort(list, (a,b)->a.name.compareTo(b.name))` — Comparator without modifying the class.' },
    { difficulty:'Intermediate', question:'What are functional interfaces in Java 8?', keywords:['functional interface','@FunctionalInterface','lambda','SAM','Predicate','Function','Consumer'], modelAnswer:'A functional interface has exactly one abstract method (SAM — Single Abstract Method), enabling it to be used with lambdas. Java 8 built-ins: `Predicate<T>`, `Function<T,R>`, `Consumer<T>`, `Supplier<T>`.', example:'Example: `Predicate<String> isLong = s -> s.length() > 5; isLong.test("Hello World")` → true.' },
    { difficulty:'Intermediate', question:'What is synchronization in Java?', keywords:['synchronized','lock','monitor','thread-safe','race condition','critical section'], modelAnswer:'Synchronization prevents multiple threads from simultaneously executing a critical section. `synchronized` keyword on methods/blocks acquires the object\'s monitor lock, ensuring mutual exclusion.', example:'Example: `public synchronized void increment(){ count++; }` — only one thread executes at a time.' },
    { difficulty:'Intermediate', question:'What are the SOLID principles in Java?', keywords:['SOLID','Single Responsibility','Open-Closed','Liskov','Interface Segregation','Dependency Inversion'], modelAnswer:'SOLID: S-Single Responsibility (class has one reason to change), O-Open/Closed (open to extension, closed to modification), L-Liskov Substitution, I-Interface Segregation, D-Dependency Inversion.', example:'Example: D — `class Service { Service(Repository repo){...} }` — inject dependency, don\'t create it inside.' },
    { difficulty:'Intermediate', question:'What is the difference between ArrayList and LinkedList?', keywords:['ArrayList','LinkedList','O(1) access','O(n) insert','doubly linked','cache','random access'], modelAnswer:'`ArrayList` uses a dynamic array — O(1) random access, O(n) insert/delete at middle. `LinkedList` uses doubly linked list — O(n) access, O(1) insert/delete at ends. ArrayList is faster for most use cases.', example:'Example: Use ArrayList for frequent reads. Use LinkedList as a deque (adding/removing from both ends).' },
    { difficulty:'Intermediate', question:'What is the Java Optional class?', keywords:['Optional','null','NullPointerException','isPresent','orElse','map','flatMap'], modelAnswer:'`Optional<T>` is a container that may or may not contain a value, forcing explicit null handling. Reduces `NullPointerException` risks. Methods: `isPresent()`, `get()`, `orElse()`, `map()`, `flatMap()`.', example:'Example: `Optional<User> user = findById(id); user.map(User::getName).orElse("Unknown");`' },
    { difficulty:'Intermediate', question:'What is dependency injection in Java?', keywords:['dependency injection','IoC','Spring','constructor injection','@Autowired','loose coupling'], modelAnswer:'DI is a design pattern where objects receive their dependencies from outside rather than creating them internally. Promotes loose coupling and testability. Spring Framework is the dominant DI container.', example:'Example: `@Service class OrderService { @Autowired private UserRepo repo; }` — Spring injects `repo` automatically.' },
    { difficulty:'Intermediate', question:'What is the difference between checked and unchecked exceptions?', keywords:['checked','unchecked','RuntimeException','compile-time','handle','declare'], modelAnswer:'Checked exceptions (extend `Exception`) must be handled or declared with `throws` at compile time. Unchecked exceptions (extend `RuntimeException`) don\'t require handling. Checked = expected failure; unchecked = programming bugs.', example:'Example: `IOException` is checked (must handle). `NullPointerException` is unchecked (programming error).' },
    { difficulty:'Intermediate', question:'What is the Builder design pattern?', keywords:['Builder','fluent','complex object','constructor','immutable','readability'], modelAnswer:'Builder pattern constructs complex objects step-by-step using a fluent interface, avoiding telescoping constructors. Produces immutable objects. Lombok\'s `@Builder` generates this automatically.', example:'Example: `User user = new User.Builder().name("Alice").age(25).email("a@b.com").build();`' },
    { difficulty:'Intermediate', question:'What is a Java thread pool?', keywords:['thread pool','ExecutorService','Executors','fixed pool','task','concurrency'], modelAnswer:'A thread pool manages a fixed set of worker threads, reusing them for multiple tasks instead of creating/destroying threads per task. Use `Executors.newFixedThreadPool(n)` or `ThreadPoolExecutor` for fine control.', example:'Example: `ExecutorService pool = Executors.newFixedThreadPool(10); pool.submit(() -> processRequest(req));`' },
    { difficulty:'Intermediate', question:'What is Java\'s garbage collection?', keywords:['GC','garbage collection','mark and sweep','young generation','old generation','G1','stop-the-world'], modelAnswer:'JVM\'s GC automatically frees unreachable objects. Young generation (Eden + Survivor): frequent minor GCs. Old generation: major GC. G1 GC (Java 9+ default) minimizes pause times via concurrent work.', example:'Example: `System.gc()` hints GC to run (not guaranteed). Objects with no references are collected automatically.' },
    { difficulty:'Intermediate', question:'What are Java annotations?', keywords:['annotation','@','metadata','@Override','@Deprecated','custom annotation','retention'], modelAnswer:'Annotations provide metadata about code. Built-in: `@Override`, `@Deprecated`, `@SuppressWarnings`. Custom annotations can have processing at compile time (annotation processors) or runtime (reflection).', example:'Example: `@NotNull`, `@Autowired`, `@Entity` — framework annotations that drive Spring/JPA behavior.' },
    { difficulty:'Intermediate', question:'What is the difference between deep copy and shallow copy in Java?', keywords:['deep copy','shallow copy','clone','Cloneable','serialization','nested'], modelAnswer:'Shallow copy copies the reference to nested objects (`.clone()` default). Deep copy creates new instances of nested objects too. Implement deep copy via custom cloning, serialization/deserialization, or copy constructors.', example:'Example: `ObjectOutputStream` + `ObjectInputStream` trick: serialize then deserialize to get a true deep copy.' },

    // ── Advanced (16) ──
    { difficulty:'Advanced', question:'How does Java\'s JIT compiler work?', keywords:['JIT','Just-In-Time','hotspot','bytecode','machine code','optimization','profiling'], modelAnswer:'JIT compiles frequently executed ("hot") bytecode to native machine code at runtime. The JVM profiles execution, identifies hot methods, and optimizes them (inlining, escape analysis, loop unrolling), improving performance iteratively.', example:'Example: A method called thousands of times gets compiled to native code, making subsequent calls near C speed.' },
    { difficulty:'Advanced', question:'What is the Java Memory Model (JMM)?', keywords:['JMM','visibility','happens-before','volatile','synchronized','CPU cache','instruction reordering'], modelAnswer:'The JMM defines how threads interact through memory. Without synchronization, threads may see stale values due to CPU caching. `volatile` ensures visibility; `synchronized` establishes happens-before guarantees; prevents reordering.', example:'Example: `volatile boolean flag = false;` — changes by one thread are immediately visible to all others.' },
    { difficulty:'Advanced', question:'What is the difference between CountDownLatch and CyclicBarrier?', keywords:['CountDownLatch','CyclicBarrier','synchronization','await','countDown','reusable','barrier'], modelAnswer:'`CountDownLatch`: one-time; threads wait until count reaches 0 (count-down by events). `CyclicBarrier`: reusable; threads wait until a fixed number arrive at a barrier point. Barrier resets after each cycle.', example:'Example: CDL — wait for service startup. CyclicBarrier — parallel computation phases where all threads must finish before proceeding.' },
    { difficulty:'Advanced', question:'What is reflection in Java?', keywords:['reflection','Class','Method','Field','invoke','getDeclaredMethods','runtime'], modelAnswer:'Reflection allows inspecting and manipulating classes, methods, and fields at runtime. Used by frameworks (Spring, Hibernate) for DI, ORM. Slower than direct calls; breaks encapsulation; use judiciously.', example:'Example: `Class<?> c = Class.forName("com.example.User"); Method m = c.getMethod("getName"); m.invoke(instance);`' },
    { difficulty:'Advanced', question:'What is the Fork/Join framework?', keywords:['ForkJoin','RecursiveTask','ForkJoinPool','divide and conquer','work stealing','parallelism'], modelAnswer:'Fork/Join framework (Java 7) enables divide-and-conquer parallelism. `ForkJoinPool` uses work-stealing (idle threads steal tasks from busy threads). Extend `RecursiveTask<T>` for tasks with return values.', example:'Example: Parallel merge sort, parallel sum of large arrays using `ForkJoinPool.commonPool()`.' },
    { difficulty:'Advanced', question:'What is CompletableFuture in Java?', keywords:['CompletableFuture','async','compose','thenApply','thenCompose','allOf','anyOf'], modelAnswer:'`CompletableFuture` (Java 8) enables non-blocking async programming with functional composition. Chain async operations with `thenApply`, `thenCompose`, `thenCombine`. Combine multiple futures with `allOf`/`anyOf`.', example:'Example: `CompletableFuture.supplyAsync(() -> fetchUser()).thenApply(user -> process(user)).thenAccept(System.out::println);`' },
    { difficulty:'Advanced', question:'What are Java Records?', keywords:['record','Java 16','immutable','data class','compact constructor','accessor'], modelAnswer:'Records (Java 16) are immutable data classes that auto-generate constructor, getters (accessors), `equals()`, `hashCode()`, and `toString()` from the record components. Designed to be transparent data carriers.', example:'Example: `record Point(int x, int y) {}` — auto-generates all boilerplate. `new Point(3,4).x()` → 3.' },
    { difficulty:'Advanced', question:'What are sealed classes in Java?', keywords:['sealed','permits','sealed class','subclass restriction','pattern matching','Java 17'], modelAnswer:'Sealed classes (Java 17) restrict which classes can extend or implement them via the `permits` clause. Enables exhaustive pattern matching and better modeling of restricted type hierarchies.', example:'Example: `sealed interface Shape permits Circle, Rectangle, Triangle {}` — only these three can implement Shape.' },
    { difficulty:'Advanced', question:'What is the module system (JPMS) introduced in Java 9?', keywords:['JPMS','Java Platform Module System','module-info','exports','requires','encapsulation','classpath'], modelAnswer:'JPMS (Java 9) introduces modules — explicitly declared dependencies (`requires`) and exports (`exports`). Enforces strong encapsulation at JVM level; replaces classpath with modulepath. Enables custom JRE images with `jlink`.', example:'Example: `module com.app { requires java.sql; exports com.app.api; }` in `module-info.java`.' },
    { difficulty:'Advanced', question:'What is garbage collection tuning in Java?', keywords:['GC tuning','heap size','Xmx','Xms','G1','ZGC','pause time','throughput'], modelAnswer:'GC tuning balances throughput vs latency. `-Xmx` sets max heap. G1GC targets pause times. ZGC/Shenandoah offer sub-millisecond pauses. Profile with GC logs before tuning. Avoid premature optimization.', example:'Example: `-XX:+UseG1GC -XX:MaxGCPauseMillis=200 -Xmx4g` for a throughput-oriented server application.' },
    { difficulty:'Advanced', question:'What is Project Loom (Virtual Threads)?', keywords:['Project Loom','virtual thread','fiber','carrier thread','structured concurrency','lightweight'], modelAnswer:'Project Loom (Java 21) introduces Virtual Threads — lightweight threads managed by the JVM, not the OS. Millions can run concurrently with minimal overhead, massively simplifying concurrent I/O code.', example:'Example: `Thread.ofVirtual().start(() -> handleRequest(req));` — can spawn 1M virtual threads handling concurrent requests.' },
    { difficulty:'Advanced', question:'What is the Reactor pattern and how does Spring WebFlux use it?', keywords:['Reactor','reactive','Mono','Flux','non-blocking','WebFlux','backpressure'], modelAnswer:'The Reactor pattern handles concurrent service requests with a single thread using an event loop + callbacks. Spring WebFlux uses Project Reactor\'s `Mono`/`Flux` types for reactive, non-blocking I/O with backpressure support.', example:'Example: `Flux<User> users = userRepo.findAll(); users.filter(u->u.active).map(UserDto::from).subscribe();`' },
    { difficulty:'Advanced', question:'What is the difference between Pessimistic and Optimistic locking?', keywords:['pessimistic locking','optimistic locking','version','database','concurrent','conflict','@Version'], modelAnswer:'Pessimistic locking acquires a DB lock immediately (SELECT FOR UPDATE) — safe but costly. Optimistic locking uses a version field; checks at commit-time if data was modified by another transaction, then retries.', example:'Example: JPA `@Version Long version;` enables optimistic locking — throws `OptimisticLockException` on conflict.' },
    { difficulty:'Advanced', question:'What is the Command Query Responsibility Segregation (CQRS) pattern?', keywords:['CQRS','Command','Query','read model','write model','Event Sourcing','scalability'], modelAnswer:'CQRS separates read (query) and write (command) operations into different models. Commands modify state; queries read state. Enables independent scaling, different data models per side, and pairs naturally with Event Sourcing.', example:'Example: Write side: `PlaceOrderCommand` → updates RDBMS. Read side: `GetOrderQuery` → reads denormalized MongoDB view.' },
    { difficulty:'Advanced', question:'What is event sourcing?', keywords:['event sourcing','event store','aggregate','replay','audit log','immutable'], modelAnswer:'Event sourcing stores state as an immutable log of events rather than current state snapshots. State is derived by replaying events. Provides full audit history, temporal queries, and easy event-driven integration.', example:'Example: `[OrderPlaced, ItemAdded, PaymentProcessed, OrderShipped]` — replaying gives current order state.' },
    { difficulty:'Advanced', question:'What are the trade-offs of microservices architecture?', keywords:['microservices','latency','distributed','service mesh','resilience','deployment','complexity'], modelAnswer:'Benefits: Independent deployability, technology diversity, fault isolation, scalability per service. Costs: Network latency, distributed tracing complexity, eventual consistency, service discovery, operational overhead.', example:'Example: Netflix uses 1000+ microservices but also has complex tooling (Hystrix, Eureka, Zipkin) to manage them.' },
  ],

  // ══════════════════════════════════════════════════════════════
  // HR INTERVIEW  —  50 questions
  // ══════════════════════════════════════════════════════════════
  'HR Interview': [
    // ── Beginner (17) ──
    { difficulty:'Beginner', question:'Tell me about yourself.', keywords:['background','experience','skills','achievements','role','education'], modelAnswer:'Structure your answer as: 1) Present role and responsibilities, 2) Past experiences/education, 3) Future goals and why this role excites you. Be concise, specific, and relevant to the job. 60-90 seconds.', example:'Example: "I\'m a computer science graduate with 2 years of experience in full-stack development. I\'m passionate about building scalable products and I\'m excited about this role because it aligns with my goal of working in AI-driven products."' },
    { difficulty:'Beginner', question:'Why do you want to work for this company?', keywords:['research','culture','mission','products','growth','alignment'], modelAnswer:'Show that you\'ve researched the company specifically. Mention their mission, products, culture, or recent achievements. Connect how the role aligns with your career goals. Avoid generic answers.', example:'Example: "I admire how [Company] is pioneering AI in healthcare. Your recent [product] impressed me because... and this role in your ML team aligns perfectly with my expertise in Python and my passion for healthcare tech."' },
    { difficulty:'Beginner', question:'What are your greatest strengths?', keywords:['strengths','relevant','specific','example','skill','accomplishment'], modelAnswer:'Choose 2-3 strengths directly relevant to the role. Back each strength with a specific example or achievement. Quantify results where possible. Don\'t be vague — "hardworking" is weak; "delivering features 20% ahead of schedule" is strong.', example:'Example: "My greatest strength is systematic problem-solving. When our app had a 3-second load time, I profiled the code, found inefficient DB queries, and optimized them — reducing load time to 0.8 seconds."' },
    { difficulty:'Beginner', question:'What is your greatest weakness?', keywords:['weakness','self-aware','improvement','steps','genuine','growth'], modelAnswer:'Pick a genuine but non-critical weakness. Show self-awareness + concrete steps you\'re taking to improve. Avoid fake weaknesses like "I work too hard." Don\'t pick weaknesses that are core requirements of the role.', example:'Example: "I tend to over-engineer solutions. I\'ve been improving by time-boxing design phases and adopting a \'make it work first\' mindset before optimizing."' },
    { difficulty:'Beginner', question:'Where do you see yourself in 5 years?', keywords:['career goals','growth','leadership','learning','progression','alignment'], modelAnswer:'Show ambition aligned with the company\'s path. Mention growing in expertise, taking on more responsibility, potentially leading teams, and contributing to company goals. Don\'t say you want the interviewer\'s job!', example:'Example: "In 5 years, I see myself as a senior engineer contributing to architectural decisions, mentoring junior developers, and leading a product area that makes a significant impact for users."' },
    { difficulty:'Beginner', question:'Why are you leaving your current job?', keywords:['growth','opportunity','new challenge','positive','forward-looking','honest'], modelAnswer:'Always keep it positive and forward-looking. Focus on what you\'re moving TOWARD (growth, impact, challenge) rather than what you\'re running FROM. Never badmouth previous employers.', example:'Example: "I\'ve learned a lot in my current role, but I\'ve reached the ceiling of growth. I\'m looking for a larger-scale technical challenge and the opportunity to work on products that impact millions of users."' },
    { difficulty:'Beginner', question:'What motivates you?', keywords:['passion','purpose','impact','learning','challenging problems','achievement'], modelAnswer:'Be authentic and specific to the role. Common genuine motivators: solving hard problems, seeing user impact, continuous learning, team collaboration, building something meaningful. Avoid: "money" or "job security."', example:'Example: "What drives me most is the moment a complex technical problem clicks — when I understand the root cause and find an elegant solution. I also find deep motivation in seeing users get value from features I build."' },
    { difficulty:'Beginner', question:'How do you handle stress and pressure?', keywords:['prioritize','deadline','calm','plan','communicate','adapt'], modelAnswer:'Show that you stay productive under pressure. Describe your method: prioritizing tasks, breaking work into chunks, communicating early about risks, taking short breaks to reset. Give a real example.', example:'Example: "I prioritize my task list, focus on the highest-impact items first, and communicate proactively with my team about deadlines. During a critical product launch, I created daily checklists that kept the team aligned and delivered on time."' },
    { difficulty:'Beginner', question:'Do you prefer to work alone or in a team?', keywords:['both','team','independent','collaboration','communication','balance'], modelAnswer:'Show you can do both effectively. Reflect that teams bring diverse perspectives and collaboration drives better outcomes, while independent work allows deep focus and ownership. Give an example of each.', example:'Example: "I enjoy both. I do my best deep work independently — coding complex systems — but I value team collaboration to catch blind spots and make better decisions. I\'m comfortable in both modes."' },
    { difficulty:'Beginner', question:'Tell me about a time you had a conflict with a coworker.', keywords:['conflict','resolution','communication','listen','compromise','outcome','STAR'], modelAnswer:'Use the STAR method. Describe the conflict briefly, focus on how you resolved it professionally through direct communication, active listening, and finding common ground. Emphasize a positive outcome.', example:'Example: "A colleague and I disagreed on system design. I scheduled a 1:1, listened to their concerns, shared my reasoning, and we agreed on a hybrid approach. The feature launched successfully and we built a stronger working relationship."' },
    { difficulty:'Beginner', question:'What are your salary expectations?', keywords:['research','market rate','range','negotiable','value','flexible'], modelAnswer:'Research market rates beforehand. Give a range based on research, your experience, and the company\'s size. Express openness to discussion. Don\'t undervalue yourself or give a number without justification.', example:'Example: "Based on market research and my experience level, I\'m looking for a range of ₹12–15 LPA, but I\'m open to discussion based on the total compensation package and growth opportunities."' },
    { difficulty:'Beginner', question:'What do you know about our products/services?', keywords:['research','product','customers','mission','market','value proposition'], modelAnswer:'Demonstrate you\'ve done genuine research. Mention specific products, their value proposition, their target users, and recent news or launches. Show excitement. Connecting products to your skills is a bonus.', example:'Example: Research the company website, LinkedIn, recent press releases, and app reviews before the interview. Mention a specific feature or initiative that genuinely interests you.' },
    { difficulty:'Beginner', question:'What accomplishment are you most proud of?', keywords:['achievement','impact','quantifiable','challenge','skills','outcome'], modelAnswer:'Choose an achievement relevant to the role with measurable impact. Structure with STAR: what was the challenge, what did you do, what was the result (with numbers if possible)?', example:'Example: "I built an automated testing suite that reduced QA time from 3 days to 4 hours, allowing us to ship features twice as fast without increasing defect rates."' },
    { difficulty:'Beginner', question:'Are you willing to relocate?', keywords:['flexible','open','discuss','preference','commitment','location'], modelAnswer:'Be honest. If you are open, say so enthusiastically. If you have constraints, be transparent but frame it positively. Ask about WFH options or relocation assistance if relevant.', example:'Example: "Yes, I\'m open to relocation for the right opportunity. Could you share more about the location and whether there are relocation support packages?"' },
    { difficulty:'Beginner', question:'How do you keep yourself updated with industry trends?', keywords:['blogs','newsletters','conferences','courses','community','practice','learning'], modelAnswer:'Name specific, credible sources you actually use: technical blogs, podcasts, courses, GitHub projects, community events. Show that learning is a genuine habit, not just a claim.', example:'Example: "I follow engineering blogs from Google and Netflix, take Coursera courses quarterly, contribute to open source on weekends, and attend local tech meetups monthly to learn from peers."' },
    { difficulty:'Beginner', question:'Why should we hire you?', keywords:['unique value','skills match','experience','enthusiasm','contribution','specific'], modelAnswer:'Make a direct, confident case for yourself. Connect your specific skills, experiences, and personal qualities to the role\'s requirements. Be specific — not generic. End with your enthusiasm for contributing.', example:'Example: "I bring 3 years of Python backend experience, have led a similar product feature from 0 to production, and I\'m deeply familiar with your tech stack. I\'m excited to bring this to your team and grow here."' },
    { difficulty:'Beginner', question:'Describe your ideal work environment.', keywords:['culture','collaboration','autonomy','growth','feedback','balance'], modelAnswer:'Describe conditions where you do your best work. Mention collaboration, autonomy, learning opportunities, clear communication, and feedback culture. Research the company\'s culture beforehand and align your answer with their values.', example:'Example: "I thrive in environments where there\'s psychological safety to experiment, where feedback is direct but constructive, and where I have ownership of my work with clear goals and support when I need it."' },

    // ── Intermediate (17) ──
    { difficulty:'Intermediate', question:'Describe a situation where you showed leadership.', keywords:['leadership','initiative','team','decision','influence','outcome','STAR'], modelAnswer:'Use STAR method. Leadership doesn\'t require a title — describe a time you took initiative, guided a team, made a key decision, or influenced others toward a goal. Focus on impact.', example:'Example: "Our team was blocked waiting for a design decision. I organized a quick decision meeting, presented 3 options with trade-offs, and we aligned within an hour — unblocking 2 weeks of engineering work."' },
    { difficulty:'Intermediate', question:'How do you handle failure?', keywords:['accountability','learn','adapt','bounce back','improve','honest'], modelAnswer:'Show accountability (not blame-shifting), the specific lesson you extracted, and what you changed going forward. Demonstrate resilience. Pick a real failure — trivial examples aren\'t convincing.', example:'Example: "My first product feature had a bug that affected 500 users. I owned the mistake, wrote a post-mortem, implemented automated tests for the edge case, and improved our deployment checklist. No repeat."' },
    { difficulty:'Intermediate', question:'Tell me about a time you managed competing priorities.', keywords:['prioritization','deadline','trade-off','stakeholder','communicate','focus'], modelAnswer:'Describe a real situation with multiple urgent tasks. Show your prioritization process (impact vs effort, stakeholder alignment, deadlines). Demonstrate clear communication and successful outcomes.', example:'Example: "I had three deadlines collide. I mapped each by impact and effort, communicated realistic dates to each stakeholder, negotiated one deadline, and delivered the other two. All stakeholders were satisfied."' },
    { difficulty:'Intermediate', question:'How do you give feedback to a colleague?', keywords:['constructive','specific','timely','private','SBI model','growth-focused'], modelAnswer:'Use a model like SBI (Situation-Behavior-Impact). Deliver promptly and privately when negative. Focus on specific behavior (not personality). Offer suggestions for improvement. Follow up.', example:'Example: "I\'d say: \'In yesterday\'s team meeting (S), when you interrupted Sarah mid-presentation (B), it made her lose her train of thought and frustrated the team (I). Would discussing points async or waiting for pauses help?\'"' },
    { difficulty:'Intermediate', question:'Describe a time you had to learn a new technology quickly.', keywords:['adaptability','learning','self-directed','deadline','resourceful','outcome'], modelAnswer:'Show your learning process: identifying key resources, building small prototypes, leveraging the community, and applying the technology to deliver real results. Quantify the timeline and outcome.', example:'Example: "I had to pick up Kubernetes in 2 weeks for a production migration. I did the official tutorial, built a test cluster, shadowed the DevOps team, and led the migration on schedule. 0 production incidents."' },
    { difficulty:'Intermediate', question:'How do you deal with a difficult manager?', keywords:['professional','communication','adapt','understand','expectations','document'], modelAnswer:'Show maturity: try to understand their perspective, communicate clearly about expectations, adapt your style, and address issues professionally. Avoid saying you\'ve never had one — not credible.', example:'Example: "I had a manager with a very different communication style. I scheduled weekly 1:1s to align expectations, documented decisions in writing, and adapted my reporting format to their preference. It improved our relationship significantly."' },
    { difficulty:'Intermediate', question:'Tell me about a time you went above and beyond.', keywords:['initiative','extra effort','impact','ownership','beyond requirements'], modelAnswer:'Describe a specific instance where you exceeded what was expected of you, explain why you chose to do so, and share the concrete outcome. Show genuine ownership and care for the work.', example:'Example: "During a critical launch, I noticed an edge-case bug not in my scope. I stayed late, fixed it, wrote tests, and documented it — preventing a potential customer-facing issue the next day."' },
    { difficulty:'Intermediate', question:'How do you make decisions with incomplete information?', keywords:['decision making','uncertainty','data','risk','assumptions','iterate'], modelAnswer:'Show a structured approach: gather available data, identify and state key assumptions clearly, assess risks, make a time-boxed decision with the best available information, and plan to validate assumptions quickly.', example:'Example: "For a new feature, user data was limited. I clearly stated our assumptions, ran a small A/B test first, reviewed results after 1 week, then committed to a full rollout once data confirmed the approach."' },
    { difficulty:'Intermediate', question:'Describe your greatest professional setback.', keywords:['setback','challenge','resilience','lesson','recovery','honest'], modelAnswer:'Be genuine and specific. Describe the setback, your emotional response (briefly), what you did to recover, and the lasting lesson you took away. Demonstrate growth and resilience.', example:'Example: "My startup failed after 18 months. It was tough, but it taught me about market validation, the importance of customer discovery, and building leaner. I applied those lessons directly in my next role."' },
    { difficulty:'Intermediate', question:'How do you prioritize your work?', keywords:['priority matrix','impact','urgency','Eisenhower','communicate','deliverables'], modelAnswer:'Describe a concrete system: urgency vs impact matrix, MoSCoW method, OKR alignment, or stakeholder discussions. Show consistency in how you prioritize and that you communicate clearly about trade-offs.', example:'Example: "I use impact vs effort assessment. High impact, low effort → do first. High impact, high effort → plan carefully. Low impact → defer or drop. I review priorities with my manager weekly."' },
    { difficulty:'Intermediate', question:'Tell me about a time you influenced without authority.', keywords:['influence','persuasion','data','stakeholder','buy-in','without authority'], modelAnswer:'Building influence without authority requires data, empathy, and relationship-building. Describe a specific situation where you used these skills to get buy-in for your idea or approach.', example:'Example: "I wanted to introduce code reviews to our team. I shared data on bug rates, showed examples of issues caught, ran a pilot with two volunteers, and presented the results. The team voted to adopt it team-wide."' },
    { difficulty:'Intermediate', question:'What is your management style?', keywords:['coaching','delegation','trust','clear expectations','feedback','adapt'], modelAnswer:'Describe your style with concrete behaviors, not just adjectives. Cover how you set expectations, delegate, give feedback, and adapt to different team members\' needs. Show awareness of different approaches.', example:'Example: "I lead by setting clear outcomes and giving autonomy on the \'how.\' I hold weekly 1:1s for coaching and blockers, give direct and timely feedback, and adapt my style — more guidance for new hires, more autonomy for seniors."' },
    { difficulty:'Intermediate', question:'How do you handle underperforming team members?', keywords:['constructive feedback','performance plan','root cause','support','document','honest'], modelAnswer:'Address early, privately, and constructively. Identify root cause (unclear expectations? skill gap? personal issue?). Create a clear improvement plan with specific, measurable goals. Follow up consistently. Escalate if needed.', example:'Example: "I had a junior engineer missing deadlines. In our 1:1, I discovered they were struggling with unfamiliar tech. We created a 4-week learning plan with weekly check-ins, and they became a reliable contributor."' },
    { difficulty:'Intermediate', question:'Tell me about a time you delivered a project under pressure.', keywords:['pressure','deadline','prioritize','communication','quality','outcome'], modelAnswer:'Describe a specific high-pressure delivery: what the stakes were, how you managed the pressure, what trade-offs you made, how you kept the team aligned, and what you delivered.', example:'Example: "We had 5 engineering days to hit a board deadline. I cut scope to the 3 critical features, reassigned tasks to strengths, held daily standups, and we shipped on time with zero critical bugs."' },
    { difficulty:'Intermediate', question:'What makes a good team?', keywords:['trust','communication','diversity','accountability','shared goals','psychological safety'], modelAnswer:'A high-performing team has psychological safety (people can take risks), clear shared goals, complementary skills, open communication, mutual accountability, and respect for diverse perspectives.', example:'Example: "The best team I was on had clear sprint goals, daily standups where everyone spoke honestly, a no-blame culture for failures, and a habit of celebrating wins together. We shipped 3x faster than any team before."' },
    { difficulty:'Intermediate', question:'Describe a time you had to adapt to a major change.', keywords:['adaptability','flexibility','change','positive','adjust','outcome'], modelAnswer:'Show your ability to respond positively to change: acknowledge the challenge, describe how you adapted your mindset and approach, and share the outcome. Avoid portraying yourself as resistant.', example:'Example: "Our team switched from Agile to OKRs overnight. I researched OKRs independently, helped translate our backlog into key results, and within a month our team\'s output clarity improved significantly."' },
    { difficulty:'Intermediate', question:'How do you build relationships with new team members?', keywords:['onboarding','1:1s','active listening','help','approachable','trust'], modelAnswer:'Describe proactive relationship-building: scheduling 1:1s early, finding ways to help them succeed, being approachable, sharing context about how the team works, and showing genuine interest in their goals.', example:'Example: "On day 1, I schedule a coffee chat to learn their background and goals. In the first week, I proactively help them unblock their first task and share the unwritten team norms to ease their ramp-up."' },

    // ── Advanced (16) ──
    { difficulty:'Advanced', question:'Tell me about a time you drove organizational change.', keywords:['change management','stakeholder alignment','resistance','data-driven','executive buy-in','impact'], modelAnswer:'Describe how you identified the need for change, built the case with data, managed resistance from stakeholders, secured executive buy-in, implemented the change in phases, and measured impact.', example:'Example: "I drove adoption of CI/CD across 5 engineering teams. I quantified the 40% time savings in testing, secured VP buy-in, ran a pilot with one team, showed results, then scaled the rollout over 3 months."' },
    { difficulty:'Advanced', question:'How do you balance technical debt and new features?', keywords:['technical debt','trade-off','prioritization','velocity','stakeholder','ratio'], modelAnswer:'Frame it as a strategic balance: quantify the cost of debt (slowing velocity by X%), allocate a sustainable ratio (e.g., 20% of sprint to debt), make it visible to stakeholders, and prioritize debt that blocks highest-value features.', example:'Example: "I track tech debt in our backlog visibly. We allocate 20% of each sprint to debt reduction. When debt was slowing our velocity by 30%, I made the ROI case to the PM and we ran a dedicated refactoring sprint."' },
    { difficulty:'Advanced', question:'How have you built and scaled an engineering team?', keywords:['hiring','onboarding','culture','process','mentoring','scaling','structure'], modelAnswer:'Describe your approach to hiring (bar-setting, culture-fit), structured onboarding, building team culture, establishing processes (code review, incident response), mentoring, and adapting structure as the team grows.', example:'Example: "I grew an engineering team from 3 to 12 in 18 months. I standardized our hiring rubric, built a 30-60-90 day onboarding plan, introduced squad structure at 10 people, and had individual growth plans for each engineer."' },
    { difficulty:'Advanced', question:'Describe a time you had to make a data-driven decision against your intuition.', keywords:['data-driven','counterintuitive','experiment','A/B test','metrics','outcome','evidence'], modelAnswer:'Show intellectual honesty — you followed data even when your gut said otherwise. Describe the situation, what the data showed, how you validated it, and the outcome when you trusted the data.', example:'Example: "I expected an onboarding redesign to improve conversion. A/B tests showed -3% instead. Despite my belief in the design, I rolled back and ran qualitative research — users preferred familiarity. Data was right."' },
    { difficulty:'Advanced', question:'How do you set direction for a team without a clear roadmap?', keywords:['vision','principles','OKR','prioritization','ambiguity','direction','strategy'], modelAnswer:'Show how you create clarity from ambiguity: define a north-star goal, establish guiding principles, use customer data and company strategy to prioritize, break down into OKRs or quarterly goals, and communicate transparently.', example:'Example: "When inheriting an undefined product area, I ran customer interviews, analyzed metrics, aligned with leadership on a 6-month north star, then defined OKRs with the team — giving us direction within 2 weeks."' },
    { difficulty:'Advanced', question:'What is your approach to developing talent on your team?', keywords:['mentoring','growth plan','career development','feedback','stretch assignment','coaching'], modelAnswer:'Describe individualized growth planning: regular career conversations, specific stretch assignments matched to growth areas, formal and informal feedback, sponsoring people for opportunities, and celebrating progress.', example:'Example: "I do quarterly career conversations with each report. I work with them to define growth goals, match them to stretch projects, and give biweekly direct feedback. Two engineers I mentored were promoted within a year."' },
    { difficulty:'Advanced', question:'How do you handle conflicting priorities from multiple executives?', keywords:['stakeholder management','conflict','alignment','escalation','prioritization','communication'], modelAnswer:'Surface the conflict transparently to all parties involved. Frame it as a resource trade-off, bring data on impact, propose a prioritized sequence, and request a decision from the appropriate decision-maker. Don\'t absorb the conflict silently.', example:'Example: "I had conflicting requests from CPO and CTO. I mapped both to OKR impact, presented the trade-off analysis transparently in a shared meeting, and we aligned on a phased approach — CTO\'s item first, CPO\'s next quarter."' },
    { difficulty:'Advanced', question:'What is psychological safety and how do you create it?', keywords:['psychological safety','trust','innovation','failure','inclusive','speak up','experiment'], modelAnswer:'Psychological safety is the belief that you won\'t be punished for speaking up, taking risks, or making mistakes. Create it by modeling vulnerability (admitting mistakes), rewarding candor, addressing blame-culture, and following up on concerns.', example:'Example: "I start sprint retros by sharing a mistake I made that week — normalizing imperfection. I publicly credit team members who flag issues early. This created a culture where people surface problems before they become crises."' },
    { difficulty:'Advanced', question:'How do you measure a team\'s health and productivity?', keywords:['DORA metrics','delivery frequency','lead time','morale','engagement','retrospective'], modelAnswer:'Use both quantitative (DORA metrics: deployment frequency, lead time, change failure rate, MTTR) and qualitative (team engagement survey, 1:1 sentiment, retrospective themes). Address root causes, not just symptoms.', example:'Example: "I track DORA metrics monthly and do quarterly team health surveys. When our MTTR (mean time to recovery) was high, we ran incident review sessions that reduced it by 60% in one quarter."' },
    { difficulty:'Advanced', question:'Tell me about a time you made a highly unpopular decision and stood by it.', keywords:['courageous','data','conviction','communication','principle','outcome'], modelAnswer:'Show principled leadership: describe the decision, why it was unpopular, how you communicated your reasoning transparently, listened to concerns, and ultimately stood by the decision and its outcome.', example:'Example: "I deprecated a popular internal tool the team loved, because it had 10x maintenance cost vs alternatives. I explained the data fully, offered migration support, tracked the friction, and we freed up 20% engineering time."' },
    { difficulty:'Advanced', question:'How do you maintain a high performance bar as a team scales?', keywords:['performance bar','consistent hiring','calibration','feedback','standards','dilution'], modelAnswer:'Maintain standards through consistent, structured hiring with calibrated interviewers; clear documented expectations per level; regular performance calibrations; and early, direct feedback when standards aren\'t met.', example:'Example: "I run quarterly performance calibrations with my peer managers, maintain a written engineering levels rubric, require unanimous hire decisions, and ensure every offer is compared against our bar — not the hiring urgency."' },
    { difficulty:'Advanced', question:'What is your philosophy on work-life balance?', keywords:['sustainable','boundaries','model','culture','burnout','long-term performance'], modelAnswer:'Show you believe high performance is sustainable, not a sprint. Leaders model healthy boundaries, protect team members from overwork, trust people to manage their time, and believe rest and renewal drive long-term productivity.', example:'Example: "I believe sustainable pace matters for long-term performance. I don\'t ping my team outside work hours, I take vacations, and I address workload concerns proactively in our 1:1s before people burn out."' },
    { difficulty:'Advanced', question:'How do you approach hiring for culture add vs culture fit?', keywords:['culture add','culture fit','diversity','inclusion','bias','values','hiring'], modelAnswer:'Culture fit can reinforce homogeneity and unconscious bias. Culture ADD focuses on shared values + unique perspective the candidate brings. Define values explicitly; hire diversity of background and thought.', example:'Example: "We shifted from \'feel like one of us\' to \'do they share our core values + what unique dimension do they add?\'  This helped us build a more innovative, inclusive team."' },
    { difficulty:'Advanced', question:'Tell me about a time you influenced product strategy as an engineer.', keywords:['product influence','data','voice','trade-off','collaboration','impact','technical perspective'], modelAnswer:'Describe how you brought the engineering perspective to a product decision: technical constraints, scalability trade-offs, or a data-driven insight that changed the product direction. Frame it as collaboration, not conflict.', example:'Example: "The PM wanted a feature that would have required 3 months of re-architecture. I proposed a simpler vertical slice that delivered 80% of the value in 2 weeks. It became our approach, and the re-arch was planned properly."' },
    { difficulty:'Advanced', question:'What is your approach to vendor and technology selection?', keywords:['vendor evaluation','build vs buy','trade-off','criteria','POC','TCO','lock-in'], modelAnswer:'Define selection criteria first (technical requirements, cost, support, security, scalability). Run a time-boxed POC. Evaluate total cost of ownership (TCO), vendor lock-in risk, community/support quality, and alignment with long-term strategy.', example:'Example: "For our logging stack, I defined 5 criteria, ran 2-week POCs with ELK and Datadog, compared total costs (including ops overhead), and chose Datadog — higher license cost but 60% lower ops cost at our scale."' },
  ],
};

// ── FIRESTORE SEEDER ──────────────────────────────────────────────────────────

let seeded = false;

/**
 * Seeds all questions into Firestore.
 * Each document: questionBank/{Domain}_{difficulty}
 * Call this ONCE when the app loads (it checks if data already exists first).
 */
export const seedQuestionsToFirestore = async (): Promise<void> => {
  if (seeded) return;

  try {
    // Check if already seeded
    const checkRef = doc(db, 'questionBank', 'JavaScript_Beginner');
    const checkSnap = await getDoc(checkRef);
    if (checkSnap.exists()) {
      console.log('[QA Bank] Firestore already seeded. Skipping.');
      seeded = true;
      return;
    }

    console.log('[QA Bank] Seeding questions to Firestore...');

    for (const [domain, questions] of Object.entries(QUESTION_BANK)) {
      const difficulties: Array<'Beginner' | 'Intermediate' | 'Advanced'> = ['Beginner', 'Intermediate', 'Advanced'];

      for (const diff of difficulties) {
        const filtered = questions.filter(q => q.difficulty === diff);
        if (filtered.length === 0) continue;

        const docId = `${domain.replace(/\s+/g, '_')}_${diff}`;
        const docRef = doc(db, 'questionBank', docId);

        await setDoc(docRef, {
          domain,
          difficulty: diff,
          questions: filtered,
          createdAt: Date.now(),
          count: filtered.length,
        });

        console.log(`[QA Bank] ✅ Seeded: ${docId} (${filtered.length} questions)`);
      }
    }

    seeded = true;
    console.log('[QA Bank] 🎉 All questions seeded to Firestore successfully!');
  } catch (err) {
    console.error('[QA Bank] Failed to seed questions:', err);
  }
};

// ── FIRESTORE READER ──────────────────────────────────────────────────────────

// Local cache to avoid repeated Firestore reads
const localCache: Record<string, QAItem[]> = {};

/**
 * Fetches questions from Firestore for a given domain and difficulty.
 * Falls back to the local QUESTION_BANK if Firestore is unavailable.
 */
export const getQuestionsFromDB = async (
  domain: string,
  difficulty: 'Beginner' | 'Intermediate' | 'Advanced'
): Promise<QAItem[]> => {
  const cacheKey = `${domain}_${difficulty}`;

  // Return cache if available
  if (localCache[cacheKey]) return localCache[cacheKey];

  try {
    const docId = `${domain.replace(/\s+/g, '_')}_${difficulty}`;
    const snap = await getDoc(doc(db, 'questionBank', docId));

    if (snap.exists()) {
      const data = snap.data();
      const questions = data.questions as QAItem[];
      localCache[cacheKey] = questions;
      console.log(`[QA Bank] ✅ Loaded ${questions.length} questions from Firestore: ${docId}`);
      return questions;
    }
  } catch (err) {
    console.warn('[QA Bank] Firestore read failed, using local fallback:', err);
  }

  // Fallback to local bank
  const fallback = (QUESTION_BANK[domain] || QUESTION_BANK['JavaScript'])
    .filter(q => q.difficulty === difficulty);
  localCache[cacheKey] = fallback;
  return fallback;
};

/**
 * Returns random N questions from the DB for a given domain and difficulty.
 */
export const getRandomQuestions = async (
  domain: string,
  difficulty: 'Beginner' | 'Intermediate' | 'Advanced',
  count: number = 10
): Promise<QAItem[]> => {
  const all = await getQuestionsFromDB(domain, difficulty);
  const shuffled = [...all].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count);
};

/**
 * Find matching QA item for a given question text.
 * Used by the local feedback engine.
 */
export const findMatchingQA = async (
  questionText: string,
  domain: string,
  difficulty: 'Beginner' | 'Intermediate' | 'Advanced'
): Promise<QAItem | null> => {
  const questions = await getQuestionsFromDB(domain, difficulty);
  const inputLower = questionText.toLowerCase();

  let bestMatch: QAItem | null = null;
  let bestScore = 0;

  for (const qa of questions) {
    const qWords = qa.question.toLowerCase().split(' ').filter(w => w.length > 3);
    const overlap = qWords.filter(w => inputLower.includes(w)).length;
    if (overlap > bestScore) {
      bestScore = overlap;
      bestMatch = qa;
    }
  }

  return bestScore >= 2 ? bestMatch : null;
};

export { QUESTION_BANK };
